      "content": "{\n  \"name\": \"@wingsky-1/dsh-mcp-manager\",\n  \"version\": \"0.2.11\",\n  \"description\": \"Manage MCP servers (stdio / streamable-http) for dsh web; tools are reached only through four middleware tools. DSH MCP 管理器：Web 侧边栏「MCP」入口，面板按状态分级展示 MCP 服务器（运行中/连接中/已配置/失败），支持快速接入（stdio / streamable-http 表单）与粘贴 mcpServers JSON 导入。已连接服务器的工具一律经中间层工具（ws_mcp_search / ws_mcp_detail / ws_mcp_call / ws_mcp_list）访问：宿主注册名 mcp__<id>__<tool> 是内部标识（id 按 (工作空间, 服务器名) 分配、不可由服务器名推导），不对模型可见，禁止直呼。\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"scripts\": {\n    \"build\": \"node ../../scripts/build/clean-lib.ts && tsc -b tsconfig.json && node ../../scripts/build/bundle-host.ts .\",\n    \"test\": \"node ../../scripts/test/run-vitest.mjs --min 121\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"prepublishOnly\": \"pnpm run typecheck && pnpm run build && pnpm test\"\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\",\n    \"./locale/*\": \"./locale/*\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\",\n      \"bannerJs\": \"import { createRequire as __mcpManagerRequire } from \\\"node:module\\\";\\nconst require = __mcpManagerRequire(import.meta.url);\"\n    },\n    \"catalog\": {\n      \"category\": \"tool\",\n      \"summary\": {\n        \"en\": \"Manage MCP servers (stdio / streamable-http) for dsh web; tools are reached only through four middleware tools.\",\n        \"zh\": \"DSH MCP 管理器：Web 侧边栏 MCP 入口，按状态分级展示服务器，支持表单与 JSON 导入接入\"\n      },\n      \"capabilities\": [\n        \"connection\",\n        \"mcp\"\n      ]\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib\",\n    \"locale\",\n    \"shared/**/*.d.ts\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\"\n  ],\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"catalog:\",\n    \"@deepseek-ai/dsh-agent\": \"catalog:\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-locale\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-store\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"catalog:\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"catalog:\",\n    \"@deepseek-ai/dsh-host-webserver\": \"catalog:\",\n    \"@deepseek-ai/dsh-llm\": \"catalog:\",\n    \"@deepseek-ai/dsh-system-prompt\": \"catalog:\",\n    \"@deepseek-ai/dsh-tools\": \"catalog:\",\n    \"@wingsky-1/dsh-shared\": \"workspace:*\",\n    \"schemastery\": \"^3.18.0\"\n  },\n  \"peerDependencies\": {\n    \"react\": \"^18.2.0\",\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.2-rc.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"react\": {\n     