    {
      "path": "packages/dsh-mcp-manager/src/server/catalog/impl/service/index.ts",
      "content": "/**\n * dsh-mcp-manager — catalog/impl/service/index.ts：目录域端口持有者（#767 B2a-wire W4）。\n *\n * 域内实现经 `catalogPorts.get()` 取数，写入只发生在组合根入口顶层的 `installCatalog`\n * （见 `src/index.ts`）。形态照 `server/upgrade/impl/service/` 的 runner：模块级只有一个\n * `const` 实例、状态收进实例字段（I9），装配与复位只经方法（方法内赋值）。\n */\nimport type { CatalogDeps } from \"../../deps.ts\";\n\n/** 目录域端口表：装配一次、域内多处读。 */\nclass CatalogPorts {\n  /** 未装配时保持 undefined——「没装配」与「装配了空实现」必须可区分（I6）。 */\n  private deps: CatalogDeps | undefined;\n\n  /** 装配：组合根递入静态模块引用；重复装配是编程错误，当场暴露。 */\n  install(deps: CatalogDeps): void {\n    if (this.deps !== undefined) throw new Error(\"dsh-mcp-manager: catalog 域只能装配一次\");\n    this.deps = deps;\n  }\n\n  /** 卸载：只复位装配标记，本域没有别的活资源要释放。 */\n  release(): void {\n    this.deps = undefined;\n  }\n\n  /**\n   * 域内取数的唯一入口。未装配即抛错而不是回落默认值：默认值会让「组合根漏装」表现成\n   * 行为正常但参数不对（目录 TTL 与检索/装箱限额静默换值），症状与本插件毫无字面关联。\n   */\n  get(): CatalogDeps {\n    const deps = this.deps;\n    if (deps === undefined) {\n      throw new Error(\n        \"dsh-mcp-manager: catalog 域未装配——组合根未在入口调用 installCatalog（src/index.ts）\",\n      );\n    }\n    return deps;\n  }\n}\n\n/** 本域唯一的装配实例：类不外放，外部 new 不出第二份端口表。 */\nexport const catalogPorts = new CatalogPorts();\n"
    },
    {
      "path": "packages/dsh-mcp-manager/src/server/api/routes-controllers.ts",
      "content": "/**\n * dsh-mcp-manager — 路由控制器工厂（#592 阶段二 Batch A：makeRoutes 消峰）。\n *\n * 每个控制器是「buildXxxRoute(manager, helpers) → WebRoute」形态的纯工厂：\n * 拆分前 makeRoutes 单函数圈复杂度 84（全仓第一），复杂度全部来自内联在各\n * 路由 handler 闭包中的方法分流与字段校验分支；拆分后 makeRoutes 退化为\n * 数组装配（comp <= 15），每个控制器的分支彼此独立、可独立理解与测试。\n *\n * 行为约束（与拆分前逐字节等价）：\n * - 路由路径与围栏（方法白名单 / loopback 豁免）取自 shared/routes.ts 单点；\n * - loopback 走快路径；非回环先经官方 admission，认证通过后才判 405；\n * - JSON body 字节上限沿用 readJsonBody 的默认行为（历史上那个显式上限\n *   常量 MAX_JSON_BODY_BYTES 已不存在）。\n *\n * 跨域取数一律经 apiPorts（见 deps.ts 与 impl/service），值为模块求值期绑定：\n * installApi 在包入口顶层完成，handler 内的 get() 取到的一定是装配后的能力。\n */\n\nimport {\n  writeJson,\n  readJsonBody,\n  readJsonBodyOutcome,\n  guardLoopbackMethod,\n} from \"../../../../../shared/host-utils.js\";\nimport type { WebRoute } from \"@deepseek-ai/dsh-host-webserver\";\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\nimport type { RoutesManager } from \"../connection/interface.ts\";\nimport type { ServerConfig } from \"../config/interface.ts\";\nimport type { McpStore } from \"../store/interface.ts\";\n// 跨端契约常量取自共享层门面（物理定义在 shared/constants.ts），不再经 workspace 门面转出。\nimport {\n  MIDDLEWARE_GLOBAL_ROOT,\n  SCOPE_PROJECT,\n  ROUTES,\n  ROUTE_FENCE,\n} from \"../../shared/interface.ts\";\nimport type { RouteName } from \"../../shared/interface.ts\";\nimport { apiPorts } from \"./impl/service/index.ts\";\nimport { queryParam } from \"./routes-helpers.ts\";\n\n/** 路由组合根注入的官方短请求 admission；类型从已使用的公开值入口推导。 */\nexport interface RouteAccess {\n  readonly remoteAdmission?: NonNullable<\n    Parameters<typeof guardLoopbackMethod>[3]\n  >[\"remoteAdmission\"];\n}\n\n/** 控制器共享 helpers（原 makeRoutes 闭包三件套，提升为显式参数）。 */\nexport interface RouteHelpers extends RouteAccess {\n  handleError(res: ServerResponse, error: unknown): void;\n  scopeParam(url: URL): string;\n  maybeSession(url: URL): Promise<void>;\n}\n\ntype Req = IncomingMessage;\ntype Res = ServerResponse;\n\n/** 所有 raw route 共用的准入与方法守卫；认证失败先于 405。 */\nfunction guardRouteAccess(req: Req, res: Res, methods: string[], helpers: RouteHelpers): boolean {\n  return guardLoopbackMethod(req, res, methods, {\n    remoteAdmission: helpers.remoteAdmission,\n  });\n}\n\n/** 提取 name 查询参数；缺失时写 400 并返回 undefined。 */\nfunction requireNameParam(url: URL, res: Res): string | undefined {\n  const name = queryParam(url, \"name\");\n  if (name === undefined || name === \"\") {\n    writeJson(res, 400, { error: \"name query parameter is required\" });\n    return undefined;\n  }\n  return name;\n}\n\n// ------------------------------------------------------------ /config\n\n/**\n * POST /config 接受的顶层键（M7 白名单）：客户端扁平 UI 形态，与\n * `normalizeUiConfig` 的**扁平**读键集同源（`ui`/`offset` 嵌套形态今天没有仓内调用方，\n * 不接受——否则白名单会退化成第三份形状定义）。\n */\nconst UI_CONFIG_KEYS: readonly string[] = [\n  \"position\",\n  \"offsetX\",\n  \"offsetY\",\n  \"blankY\",\n  \"zIndexBase\",\n];\n\n/** UI 配置读写（loopback 快路径；非回环先经官方 admission，之后才分方法和校体）。 */\nexport function buildConfigRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES.config,\n    handler: async (req: Req, res: Res) => {\n      const method = String(req.method);\n      const methods = [...ROUTE_FENCE.config.loopbackExempt, ...ROUTE_FENCE.config.guarded];\n      // GET 的读取面、POST 的写入面和未知方法的 405 都排在认证之后。非回环 GET\n      // 不再因历史只读豁免绕过官方 Host/Origin/credential admission。\n      if (!guardRouteAccess(req, res, methods, helpers)) return;\n      if (ROUTE_FENCE.config.loopbackExempt.includes(method)) {\n        try {\n          writeJson(res, 200, manager.uiConfig());\n        } catch (error) {\n          helpers.handleError(res, error);\n        }\n        return;\n      }\n      // POST：写入浮窗 UI 配置（position / offsetX / offsetY / blankY / zIndexBase）。\n      // 写操作须为 loopback 或通过官方 admission；经设置命名空间落盘（Config.ui），触发\n      // scope.watch → onChange → SSE 广播一帧，客户端收到后重新 GET /config 就地更新\n      // 浮窗位置，无需重启/轮询。\n      //\n      // M7：**未知顶层键一律 400 且不落盘**（校验在任何 uiUpdate 之前）。静默丢键会让\n      // 调用方以为写入生效——错就要说错，不能把「没生效」写成 200。\n      if (ROUTE_FENCE.config.guarded.includes(method)) {\n        let body: unknown;\n        try {\n          body = await readJsonBody(req);\n        } catch {\n          writeJson(res, 400, { error: \"invalid JSON body\" });\n          return;\n        }\n        if (typeof body !== \"object\" || body === null) {\n          writeJson(res, 400, { error: \"invalid JSON body\" });\n          return;\n        }\n        try {\n          const rec = body as Record<string, unknown>;\n          const unknownKeys = Object.keys(rec).filter((key) => !UI_CONFIG_KEYS.includes(key));\n          if (unknownKeys.length > 0) {\n            writeJson(res, 400, { error: `unknown config key(s): ${unknownKeys.join(\", \")}` });\n            return;\n          }\n          writeJson(res, 200, await manager.updateUiConfig(body));\n        } catch (error) {\n          helpers.handleError(res, error);\n        }\n        return;\n      }\n      // guardRouteAccess 已对白名单外方法写 405；保留兜底与共享守卫文案同形。\n      writeJson(res, 405, { error: `method not allowed: ${req.method}` });\n    },\n  };\n}\n\n// ------------------------------------------------------------ /servers\n\n/** 服务器集合变更（POST 添加 / PATCH 更新 / DELETE 删除）：写操作面，与 GET 快照分离。\n *\n * 回答「如何变更集合？」——读快照（GET）留在 handler 内，方法分流后写操作整体下沉。\n * 返回 true 表示已处理并应答；false 表示方法不在写集合内（调用方继续 405）。 */\nasync function handleServersMutation(\n  method: string,\n  url: URL,\n  req: Req,\n  res: Res,\n  manager: RoutesManager,\n  helpers: RouteHelpers,\n): Promise<boolean> {\n  if (method === \"POST\") {\n    await createServer(req, res, manager, helpers);\n    return true;\n  }\n  if (method !== \"PATCH\" && method !== \"DELETE\") return false;\n  const name = requireNameParam(url, res);\n  if (name === undefined) return true;\n  await changeServer(method, name, url, req, res, manager, helpers);\n  return true;\n}\n\n/** POST /servers：新增单台（201 + 投影 + 快照）。 */\nasync function createServer(\n  req: Req,\n  res: Res,\n  manager: RoutesManager,\n  helpers: RouteHelpers,\n): Promise<void> {\n  const body = await readJsonBody(req);\n  if (body === undefined) {\n    writeJson(res, 400, { error: \"invalid JSON body\" });\n    return;\n  }\n  const { workspace } = apiPorts.get();\n  try {\n    const rec = body as Record<string, unknown>;\n    const scope = workspace.normalizeScope(rec.scope as string);\n    if (typeof rec.cwd === \"string\" && rec.cwd !== \"\") await manager.setSession(rec.cwd);\n    const created = await manager.add(rec, scope);\n    // #770-L3 只读投影：200 响应 server 字段不再明文回显写路径原文（与 A3 同一红线伞）。\n    // 缺省回落原文：外部 RoutesManager 实现未提供 summarize 时自身无秘密可泄（同 redactError 兼容口径）。\n    const server =\n      typeof manager.summarize === \"function\" ? manager.summarize(created, scope) : created;\n    writeJson(res, 201, { server, summary: manager.summary() });\n  } catch (error) {\n    helpers.handleError(res, error);\n  }\n}\n\n/** PATCH /servers（更新）/ DELETE /servers（移除）：按请求固定目标项目根。 */\nasync function changeServer(\n  method: string,\n  name: string,\n  url: URL,\n  req: Req,\n  res: Res,\n  manager: RoutesManager,\n  helpers: RouteHelpers,\n): Promise<void> {\n  try {\n    const scope = helpers.scopeParam(url);\n    const cwd = queryParam(url, \"cwd\");\n    const root = await manager.rootForRequest(scope, cwd);\n    if (method === \"DELETE\") {\n      await manager.remove(name, scope, scope === SCOPE_PROJECT ? root : cwd);\n      writeJson(res, 200, { ok: true, summary: manager.summaryForRoot(root) });\n      return;\n    }\n    const body = await readJsonBody(req);\n    if (body === undefined) {\n      writeJson(res, 400, { error: \"invalid JSON body\" });\n      return;\n    }\n    const updated = await manager.update(\n      name,\n      body as Record<string, unknown>,\n      scope,\n      scope === SCOPE_PROJECT ? root : cwd,\n    );\n    // #770-L3 只读投影：同 POST 分支（与 A3 同一红线伞；缺省回落原文口径同上）。\n    const server = manager.summarizeForRoot(updated, scope, root);\n    const status = typeof (body as Record<string, unknown>).enabled === \"boolean\" ? 202 : 200;\n    writeJson(res, status, { server, summary: manager.summaryForRoot(root) });\n  } catch (error) {\n    helpers.handleError(res, error);\n  }\n}\n\n/** 服务器集合 CRUD：GET 快照（纯读）/ POST 添加 / PATCH 更新 / DELETE 删除。 */\nexport function buildServersRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES.servers,\n    handler: async (req: Req, res: Res) => {\n      const url = new URL(req.url ?? \"/\", \"http://localhost\");\n      const method = req.method ?? \"GET\";\n      if (!guardRouteAccess(req, res, ROUTE_FENCE.servers.guarded, helpers)) return;\n      if (method === \"GET\") {\n        try {\n          // 按请求 cwd 读取对应项目，不切会话或广播 SSE，避免多页面互相切换。\n          const cwd = queryParam(url, \"cwd\");\n          const summary = cwd === undefined ? manager.summary() : await manager.summaryForCwd(cwd);\n          writeJson(res, 200, summary);\n        } catch (error) {\n          helpers.handleError(res, error);\n        }\n        return;\n      }\n      if (await handleServersMutation(method, url, req, res, manager, helpers)) return;\n      writeJson(res, 405, { error: `method not allowed: ${method}` });\n    },\n  };\n}\n\n// ------------------------------------------------------------ /session 与 /resume\n\n/** 会话切换（跟随会话的项目级 MCP）。 */\nexport function buildSessionRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES.session,\n    handler: async (req: Req, res: Res) => {\n      if (!guardRouteAccess(req, res, ROUTE_FENCE.session.guarded, helpers)) return;\n      const body = await readJsonBody(req);\n      if (body === undefined || typeof (body as Record<string, unknown>).cwd !== \"string\") {\n        writeJson(res, 400, { error: \"body must include a cwd string\" });\n        return;\n      }\n      try {\n        await manager.setSession((body as Record<string, unknown>).cwd as string);\n        writeJson(res, 200, { ok: true, summary: manager.summary() });\n      } catch (error) {\n        helpers.handleError(res, error);\n      }\n    },\n  };\n}\n\n/** 解析 resume 可选请求体：回答「本次要固定哪个 root？」——形状与必填校验。\n *\n * 返回携带 cwd 的成功体（缺 cwd 即回落既有绑定），或写 400 用的错误文案；\n * 数组是合法 JSON 但不是请求体对象，同样拒绝且不触发恢复。 */\nfunction parseResumeCwd(value: object): { ok: true; cwd?: string } | { ok: false; error: string } {\n  if (Array.isArray(value)) return { ok: false, error: \"invalid JSON body\" };\n  const rec = value as Record<string, unknown>;\n  if (!(\"cwd\" in rec)) return { ok: true };\n  if (typeof rec.cwd !== \"string\") return { ok: false, error: \"body cwd must be a string\" };\n  return { ok: true, cwd: rec.cwd };\n}\n\n/** 切回前台可用性恢复（非强制，#1120）：body 可选 { cwd?: string }。\n * - 无 body（旧客户端）：回落既有绑定，manager.resumeReconnect() 无参；\n * - 有 cwd（含 \"\")：本次固定 root（\"\"=明确无工作区→@global，不回落他人绑定）；\n * - 非对象（含数组，readJsonBodyOutcome 把数组归 json 需此处拒）/ cwd 非字符串 → 400\n *   且不触发恢复。路径/围栏/方法分流不动。 */\nexport function buildResumeRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES.resume,\n    handler: async (req: Req, res: Res) => {\n      if (!guardRouteAccess(req, res, ROUTE_FENCE.resume.guarded, helpers)) return;\n      try {\n        if (typeof manager.resumeReconnect !== \"function\")\n          throw new Error(\"resumeReconnect unavailable\");\n        const outcome = await readJsonBodyOutcome(req);\n        if (outcome.kind === \"invalid\") {\n          writeJson(res, 400, { error: \"invalid JSON body\" });\n          return;\n        }\n        if (outcome.kind === \"absent\") {\n          await manager.resumeReconnect();\n          writeJson(res, 200, { ok: true, summary: manager.summary() });\n          return;\n        }\n        const parsed = parseResumeCwd(outcome.value);\n        if (!parsed.ok) {\n          writeJson(res, 400, { error: parsed.error });\n          return;\n        }\n        if (parsed.cwd === undefined) {\n          await manager.resumeReconnect();\n        } else {\n          await manager.resumeReconnect(parsed.cwd);\n        }\n        writeJson(res, 200, { ok: true, summary: manager.summary() });\n      } catch (error) {\n        helpers.handleError(res, error);\n      }\n    },\n  };\n}\n\n// ------------------------------------------------------------ connect / disconnect / reconnect\n\n/** 单服务器连接/断开/重连路由：按请求固定目标项目根。 */\nfunction buildNameActionRoute(\n  route: RouteName,\n  action: (name: string, scope: string, cwd: string | undefined) => Promise<string>,\n  manager: RoutesManager,\n  helpers: RouteHelpers,\n): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES[route],\n    handler: async (req: Req, res: Res) => {\n      if (!guardRouteAccess(req, res, ROUTE_FENCE[route].guarded, helpers)) return;\n      const url = new URL(req.url ?? \"/\", \"http://localhost\");\n      const name = requireNameParam(url, res);\n      if (name === undefined) return;\n      try {\n        const root = await action(name, helpers.scopeParam(url), queryParam(url, \"cwd\"));\n        writeJson(res, 202, { ok: true, summary: manager.summaryForRoot(root) });\n      } catch (error) {\n        helpers.handleError(res, error);\n      }\n    },\n  };\n}\n\n/** POST /servers/connect：连接单服务器。 */\nexport function buildConnectRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return buildNameActionRoute(\n    \"connect\",\n    (name, scope, cwd) => manager.acceptConnection(name, scope, cwd),\n    manager,\n    helpers,\n  );\n}\n\n/** POST /servers/disconnect：断开单服务器。 */\nexport function buildDisconnectRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return buildNameActionRoute(\n    \"disconnect\",\n    (name, scope, cwd) => manager.disconnectForRequest(name, scope, cwd),\n    manager,\n    helpers,\n  );\n}\n\n/** POST /servers/reconnect：重连单服务器。 */\nexport function buildReconnectRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return buildNameActionRoute(\n    \"reconnect\",\n    (name, scope, cwd) => manager.acceptConnection(name, scope, cwd),\n    manager,\n    helpers,\n  );\n}\n\n// ------------------------------------------------------------ /import/json\n\n/** 单台服务器的导入落点：在册且未开 overwrite → 记 skipped；在册开 overwrite → update；否则 add。 */\nexport async function importOneServer(\n  server: ServerConfig,\n  store: McpStore,\n  scope: string,\n  overwrite: boolean,\n  manager: RoutesManager,\n  imported: string[],\n  skipped: string[],\n): Promise<void> {\n  if (store.find(server.name) === undefined) {\n    await manager.add(server, scope);\n    imported.push(server.name);\n    return;\n  }\n  if (!overwrite) {\n    skipped.push(server.name);\n    return;\n  }\n  await manager.update(server.name, server, scope);\n  imported.push(server.name);\n}\n\n/** 导入 mcpServers JSON（同名 skip，overwrite=true 时更新）。 */\nexport function buildImportJsonRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES.importJson,\n    handler: async (req: Req, res: Res) => {\n      const { workspace, configModel } = apiPorts.get();\n      if (!guardRouteAccess(req, res, ROUTE_FENCE.importJson.guarded, helpers)) return;\n      const body = await readJsonBody(req);\n      if (body === undefined || typeof (body as Record<string, unknown>).json !== \"string\") {\n        writeJson(res, 400, { error: \"body must include a json string\" });\n        return;\n      }\n      const imported: string[] = [];\n      const skipped: string[] = [];\n      try {\n        const rec = body as Record<string, unknown>;\n        const scope = workspace.normalizeScope(rec.scope as string);\n        if (typeof rec.cwd === \"string\" && rec.cwd !== \"\") await manager.setSession(rec.cwd);\n        const store = scope === SCOPE_PROJECT ? await manager.projectStoreOrThrow() : manager.store;\n        const servers = configModel.parseClaudeJson(rec.json as string);\n        for (const server of servers) {\n          await importOneServer(\n            server,\n            store,\n            scope,\n            rec.overwrite === true,\n            manager,\n            imported,\n            skipped,\n          );\n        }\n      } catch (error) {\n        helpers.handleError(res, error);\n        return;\n      }\n      writeJson(res, 200, { imported, skipped, summary: manager.summary() });\n    },\n  };\n}\n\n// ------------------------------------------------------------ /tool-disable\n\n/** 解析 tool-disable 请求体：回答「调用方要禁哪把工具？」——形状与必填校验。\n *\n * 返回携带 server/tool/disabled 的成功体，或写 400 用的错误文案；路由一致性\n * （全名 root 是否属于当前工作空间）与执行留在 handler 内（不同问题）。 */\nfunction parseToolDisableBody(\n  body: unknown,\n): { ok: true; server: string; tool: string; disabled: boolean } | { ok: false; error: string } {\n  if (body === undefined || typeof body !== \"object\" || body === null) {\n    return { ok: false, error: \"invalid JSON body\" };\n  }\n  const rec = body as Record<string, unknown>;\n  const server = typeof rec.server === \"string\" ? rec.server : \"\";\n  const tool = typeof rec.tool === \"string\" ? rec.tool : \"\";\n  const disabled = rec.disabled === true;\n  if (server === \"\" || tool === \"\") {\n    return { ok: false, error: \"server 与 tool 均为必填\" };\n  }\n  return { ok: true, server, tool, disabled };\n}\n\n/** 路由一致性校验：@global 或当前会话项目 root 才可写（防跨空间串台）。放行返回 null。 */\nexport function workspaceMismatchError(\n  root: string,\n  sessionRoot: string | undefined,\n  server: string,\n): string | null {\n  if (root === MIDDLEWARE_GLOBAL_ROOT || root === sessionRoot) return null;\n  return `server ${JSON.stringify(server)} 不属于当前工作空间；路由一致性校验失败（防跨空间串台）`;\n}\n\n/** 工具级禁用开关（PATCH；root 路由一致性校验防跨空间串台）。 */\nexport function buildToolDisableRoute(manager: RoutesManager, helpers: RouteHelpers): WebRoute {\n  return {\n    kind: \"exact\",\n    path: ROUTES.toolDisable,\n    handler: async (req: Req, res: Res) => {\n      const { workspace } = apiPorts.get();\n      if (!guardRouteAccess(req, res, ROUTE_FENCE.toolDisable.guarded, helpers)) return;\n      const url = new URL(req.url ?? \"/\", \"http://localhost\");\n      const body = await readJsonBody(req);\n      const parsedBody = parseToolDisableBody(body);\n      if (!parsedBody.ok) {\n        writeJson(res, 400, { error: parsedBody.error });\n        return;\n      }\n      const { server, tool, disabled } = parsedBody;\n      // 路由一致性：server 全名 root 必须属于当前工作空间（或 @global）。\n      const parsed = workspace.parseFullServerName(server);\n      if (parsed === undefined) {\n        writeJson(res, 400, { error: \"server 格式非法，应为 @<root>/<server>\" });\n        return;\n      }\n      const root = parsed.root;\n      const cwdParam = queryParam(url, \"cwd\");\n      if (cwdParam !== undefined && cwdParam !== \"\") await manager.setSession(cwdParam);\n      const mismatch = workspaceMismatchError(root, manager.projectRoot, server);\n      if (mismatch !== null) {\n        writeJson(res, 400, { error: mismatch });\n        return;\n      }\n      if (typeof manager.setToolDisabled !== \"function\") {\n        writeJson(res, 400, { error: \"tool-disable not writable: middleware unavailable\" });\n        return;\n      }\n      try {\n        // #392 遗留④：tool 参数先归一化（剥 mcp__<id>__ 直呼前缀）再入禁用表——\n        // 旧客户端/手工 API 可能提交带前缀名，此前原样存键导致 guard 层查裸名不命中、\n        // 禁用静默无效。跨 server 前缀（剥后仍 mcp__ 开头）由 normalizeToolName 抛错。\n        const toolName = workspace.normalizeToolName(parsed.server, tool, \"tool-disable\");\n        await manager.setToolDisabled(root, parsed.server, toolName, disabled);\n        writeJson(res, 200, { ok: true, summary: manager.summary() });\n      } catch (error) {\n        helpers.handleError(res, error);\n      }\n    },\n  };\n}\n"
    },
    {
      "path": "shared/host-utils.ts",
      "content": "// dsh 插件家族共享层 — 宿主端辅助函数（单一事实源）。\n//\n// 历史：writeJson 5 份、errorMessage 4 份、readBody 4 份 3 档 limit 在各插件\n// 逐字复制并已漂移。统一由本模块提供；readBody 的 limit 由调用方显式传入，\n// 消除隐式差异。\n\nimport { Buffer } from \"node:buffer\";\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\n\n/**\n * Loopback 围栏判定参数。\n * - allowCrossSiteNoCors（#549）：仅 serve 类资源伺服路由使用——放行「显式\n *   sec-fetch-mode: no-cors」的跨站子资源请求（sandbox iframe opaque origin\n *   的相对路径 css/js/img 加载）；cors fetch/XHR 与 navigate 仍拒绝。\n *   普通 /api 路由必须保持默认（不传 options）拒绝一切 cross-site。\n */\nexport interface LoopbackOptions {\n  allowCrossSiteNoCors?: boolean;\n  /**\n   * 非回环请求的官方认证源。必须每次请求现取 `ctx.connection`，不得缓存 service 实例。\n   * 未提供、读取失败或 connection 已卸载时由 routeFenceRejection fail-closed。\n   */\n  remoteAdmission?: RemoteAdmissionSource;\n  /** 长连接请求的官方 peer admission；仅 SSE/流式 route 使用。 */\n  remotePeerAdmission?: RemotePeerAdmissionSource;\n}\n\n/** 官方 `ctx.connection.requestRejection()` 的最小结果面。 */\nexport type RemoteAdmissionRejection = 401 | 403 | undefined;\n\n/** 一次非回环请求的官方 admission；`undefined` 表示 Host/Origin 与凭据均已通过。 */\nexport type RemoteAdmission = (request: IncomingMessage) => RemoteAdmissionRejection;\n\n/** admission 的动态来源；每次 HTTP 请求调用一次，使 connection 替换或卸载立即生效。 */\nexport type RemoteAdmissionSource = () => RemoteAdmission | undefined;\n\n/**\n * 官方 `PeerScope` 中本层绑定长连接所需的最小公开面。rc.1 的 PeerScope.ctx 是随 Peer\n * dispose 的 Cordis Context；这里只保留 `effect`，不持有认证材料，也不复制认证算法。\n */\nexport interface RemotePeerScope {\n  readonly ctx: {\n    effect(execute: () => () => void, label?: string): unknown;\n  };\n}\n\n/** 官方 `connection.admit()` 的成功/拒绝结果。 */\nexport type RemotePeerAdmissionResult =\n  { readonly peer: RemotePeerScope } | { readonly rejection: 401 | 403 };\n\n/** 一次非回环长连接请求的官方 admission。 */\nexport type RemotePeerAdmission = (request: IncomingMessage) => RemotePeerAdmissionResult;\n\n/** peer admission 的动态来源；同样必须在每次连接请求时重新读取 connection。 */\nexport type RemotePeerAdmissionSource = () => RemotePeerAdmission | undefined;\n\n/** cordis Context 的最小读取面；`strict: false` 是面向可选服务探测的官方调用形态。 */\nexport interface ConnectionLookupContext {\n  get(name: string, strict?: boolean): unknown;\n}\n\n/**\n * Loopback 围栏：请求必须来自回环地址 + 回环 Host，且满足跨站/来源约束，\n * 否则拒绝。默认拒绝一切 `sec-fetch-site: cross-site` 请求（DNS 重绑定 +\n * 跨站防御）；仅当 `options.allowCrossSiteNoCors` 为 true 时，**显式带\n * `sec-fetch-mode: no-cors` 的跨站子资源请求**放行（见 issue #549：\n * sandbox iframe 的 opaque origin 会使其相对路径子资源请求（css/js/img）\n * 一律呈 cross-site，serve 虚拟伺服需放行 no-cors 标签型加载，但 cors\n * fetch/XHR 与 navigate 仍拒绝）。\n *\n * 跨站放行是安全语义变更点，**只允许 serve 类资源伺服路由使用**；\n * 普通 /api 路由必须保持默认拒绝。\n *\n * @param request - Node http 请求对象。\n * @param options - 可选判定参数。\n * @returns 是否允许。\n */\n/**\n * 对端地址是否回环（IPv4 / IPv6 / IPv4-mapped 三种写法）。fail-closed：拿不到地址即拒绝。\n *\n * 单立一函数是因为它与 Host 头是**两个不同的事实**：前者在传输层（谁连过来的），\n * 后者在应用层（他说自己是谁）。合成一条 if 时，「改 Host 白名单」会连带改到对端判定。\n */\nfunction isLoopbackPeerAddress(request: IncomingMessage): boolean {\n  const address = request.socket?.remoteAddress;\n  return address === \"127.0.0.1\" || address === \"::1\" || address === \"::ffff:127.0.0.1\";\n}\n\n/**\n * Host 头解析与判定：必须是 127.0.0.1 / localhost / [::1]，否则拒绝。\n * 返回解析好的 URL（同源比较要用它的 host），解析失败或不在白名单即 undefined。\n */\nfunction loopbackHostUrlOf(request: IncomingMessage): URL | undefined {\n  const host = request.headers.host;\n  if (typeof host !== \"string\") return undefined;\n  let hostUrl: URL;\n  try {\n    hostUrl = new URL(`http://${host}`);\n  } catch {\n    return undefined;\n  }\n  if (\n    hostUrl.hostname !== \"127.0.0.1\" &&\n    hostUrl.hostname !== \"localhost\" &&\n    hostUrl.hostname !== \"[::1]\"\n  ) {\n    return undefined;\n  }\n  return hostUrl;\n}\n\n/**\n * 跨站判定（#549）：默认拒绝一切 cross-site；仅 serve 资源路由经 allowCrossSiteNoCors\n * 放行「显式 no-cors」的跨站子资源（标签型加载）。\n * fail-closed：cross-site 请求缺少 no-cors 标记（含头缺失的防御语义）一律拒绝，不猜测放行。\n * 同源（无 sec-fetch-site 或非 cross-site）恒放行——同源与否由 Origin 头那一段再判一次。\n */\nfunction crossSiteRequestAllowed(request: IncomingMessage, options: LoopbackOptions): boolean {\n  if (request.headers[\"sec-fetch-site\"] !== \"cross-site\") return true;\n  return options.allowCrossSiteNoCors === true && request.headers[\"sec-fetch-mode\"] === \"no-cors\";\n}\n\nexport function isLoopbackRequest(\n  request: IncomingMessage,\n  options: LoopbackOptions = {},\n): boolean {\n  if (!isLoopbackPeerAddress(request)) return false;\n  const hostUrl = loopbackHostUrlOf(request);\n  if (hostUrl === undefined) return false;\n  if (!crossSiteRequestAllowed(request, options)) return false;\n  const origin = request.headers.origin;\n  if (origin === undefined) return true;\n  try {\n    return new URL(origin).host === hostUrl.host;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * 从当前 Context 建立动态 admission 源。\n *\n * 闭包只保留 Context；每次请求重新 `get(\"connection\", false)`，不缓存 connection 或方法。\n */\nexport function liveConnectionAdmission(ctx: ConnectionLookupContext): RemoteAdmissionSource {\n  return () => {\n    const connection = ctx.get(\"connection\", false);\n    if (\n      connection === null ||\n      typeof connection !== \"object\" ||\n      !(\"requestRejection\" in connection) ||\n      typeof connection.requestRejection !== \"function\"\n    ) {\n      return undefined;\n    }\n    const requestRejection = connection.requestRejection;\n    return (request) => requestRejection.call(connection, request) as RemoteAdmissionRejection;\n  };\n}\n\nfunction isRemotePeerScope(value: unknown): value is RemotePeerScope {\n  return (\n    value !== null &&\n    typeof value === \"object\" &&\n    \"ctx\" in value &&\n    value.ctx !== null &&\n    typeof value.ctx === \"object\" &&\n    \"effect\" in value.ctx &&\n    typeof value.ctx.effect === \"function\"\n  );\n}\n\n/** 现读可选动态源；source 缺失或读取抛错都由调用方统一 fail-closed。 */\nfunction currentRemoteSource<T>(source?: () => T | undefined): T | undefined {\n  try {\n    return source?.();\n  } catch {\n    return undefined;\n  }\n}\n\n/** 官方短请求 admission 结果只接受 undefined / 401 / 403，其余一律收敛为 403。 */\nfunction normalizeRemoteRejection(value: unknown): RemoteAdmissionRejection {\n  if (value === undefined) return undefined;\n  return value === 401 || value === 403 ? value : 403;\n}\n\n/** 官方长连接 admission 结果只接受有效 PeerScope 或 401/403，其余一律 fail-closed。 */\nfunction normalizePeerAdmissionResult(value: unknown): RemotePeerAdmissionResult {\n  if (value !== null && typeof value === \"object\") {\n    if (\"peer\" in value && isRemotePeerScope(value.peer)) return { peer: value.peer };\n    if (\"rejection\" in value && (value.rejection === 401 || value.rejection === 403)) {\n      return { rejection: value.rejection };\n    }\n  }\n  return { rejection: 403 };\n}\n\n/** 从当前 Context 建立长连接 peer admission 源，成功结果保留官方 PeerScope。 */\nexport function liveConnectionPeerAdmission(\n  ctx: ConnectionLookupContext,\n): RemotePeerAdmissionSource {\n  return () => {\n    const connection = ctx.get(\"connection\", false);\n    if (\n      connection === null ||\n      typeof connection !== \"object\" ||\n      !(\"admit\" in connection) ||\n      typeof connection.admit !== \"function\"\n    ) {\n      return undefined;\n    }\n    const admit = connection.admit;\n    return (request) => normalizePeerAdmissionResult(admit.call(connection, request) as unknown);\n  };\n}\n\n/**\n * 长连接请求认证：loopback 仍走旧快路径且不绑定 connection Peer；非回环必须从\n * 当前官方 connection admission 拿到 PeerScope，供调用方注册 peer.ctx.effect()。\n */\nexport function admitLongLivedRequest(\n  request: IncomingMessage,\n  options: LoopbackOptions = {},\n): { readonly peer?: RemotePeerScope } | { readonly rejection: 401 | 403 } {\n  if (isLoopbackPeerAddress(request)) {\n    return isLoopbackRequest(request, options) ? {} : { rejection: 403 };\n  }\n\n  const admission = currentRemoteSource(options.remotePeerAdmission);\n  if (typeof admission !== \"function\") return { rejection: 403 };\n\n  try {\n    return normalizePeerAdmissionResult(admission(request));\n  } catch {\n    return { rejection: 403 };\n  }\n}\n\n/**\n * 把长连接清理登记到官方 PeerScope 的 ctx.effect；Peer 释放/connection 卸载时自动执行。\n * 返回的 disposer 供客户端先断开时注销 effect，重复调用由 Cordis 保持幂等。\n */\nexport function bindPeerLifecycle(\n  peer: RemotePeerScope,\n  cleanup: () => void,\n  label: string,\n): () => void {\n  const dispose = peer.ctx.effect(() => () => cleanup(), label);\n  let disposed = false;\n  return () => {\n    if (disposed) return;\n    disposed = true;\n    if (typeof dispose === \"function\") void dispose();\n  };\n}\n\n/**\n * 路由认证裁决：回环快路径保持原样，非回环交给官方 connection admission。\n *\n * 非回环路径中，source/service/method 缺失、抛错或返回未知值一律 403。`undefined`\n * 只来自当前官方 admission，表示 Host/Origin 与浏览器/API 凭据均已通过。\n */\nexport function routeFenceRejection(\n  request: IncomingMessage,\n  options: LoopbackOptions = {},\n): RemoteAdmissionRejection {\n  if (isLoopbackPeerAddress(request)) {\n    return isLoopbackRequest(request, options) ? undefined : 403;\n  }\n\n  const admission = currentRemoteSource(options.remoteAdmission);\n  if (typeof admission !== \"function\") return 403;\n\n  try {\n    return normalizeRemoteRejection(admission(request));\n  } catch {\n    return 403;\n  }\n}\n\n/**\n * 路由认证 + 方法白名单低阶守卫。\n *\n * **对本守卫的执行顺序**：回环快路径；非回环走官方 connection admission，\n * 401/403 原样返回；认证通过后才检查方法，方法不在白名单 → 405。该顺序仅对\n * **套本守卫的端点**成立——个别端点（如\n * mcp-manager /config）是端点级方法分流先于 loopback 的刻意例外，不适用。\n *\n * @param req - Node http 请求对象。\n * @param res - 响应对象。\n * @param methods - 允许的 HTTP 方法白名单。\n * @param loopbackOptions - 透传给\n *   isLoopbackRequest 的可选判定参数；`remoteAdmission` 只在非回环路径启用。\n * @returns 是否放行（true 时调用方继续处理请求）。\n */\nexport function guardLoopbackMethod(\n  req: IncomingMessage,\n  res: ServerResponse,\n  methods: string[],\n  loopbackOptions?: LoopbackOptions,\n): boolean {\n  const rejection = routeFenceRejection(req, loopbackOptions);\n  if (rejection !== undefined) {\n    writeJson(res, rejection, {\n      error: rejection === 401 ? \"unauthorized\" : \"forbidden: loopback-only\",\n    });\n    return false;\n  }\n  // `req.method` 在 @types/node 上是 `string | undefined`。断言不改变运行时取值：\n  // 缺 method 时 includes 仍为 false，照原样落 405，不存在被误放行的分支。\n  if (!methods.includes(req.method as string)) {\n    writeJson(res, 405, { error: `method not allowed: ${req.method}` });\n    return false;\n  }\n  return true;\n}\n\n/**\n * 写 JSON 响应（统一带 referrer-policy 头，防 referrer 泄露）。\n * @param res - 响应对象。\n * @param status - HTTP 状态码。\n * @param payload - 序列化为 JSON 的负载。\n */\nexport function writeJson(res: ServerResponse, status: number, payload: unknown): void {\n  res.writeHead(status, {\n    \"content-type\": \"application/json; charset=utf-8\",\n    \"referrer-policy\": \"no-referrer\",\n  });\n  res.end(JSON.stringify(payload));\n}\n\n/**\n * 序列化一帧 SSE data 行（输出形如 `data: <json>\\n\\n`）。\n * 与 mcp-manager / notifier / provider-usage 三处历史实现逐字同构（#472 收敛）。\n * JSON.stringify(undefined) 返回 undefined，拼接为 `data: undefined\\n\\n`；含真实\n * 换行的 payload 由 JSON 转义为字面 `\\n`，不拆多行 data 帧。现状三处均无调用点\n * 传 undefined（payload 恒为对象字面量），该行为仅为对齐历史、不额外兜底，\n * 非承诺契约——若未来收紧（抛错/省略）不视为破坏兼容（需单开决策）。\n * @param payload - 序列化为 JSON 的 SSE 帧负载。\n * @returns SSE data 帧文本。\n */\nexport function sseData(payload: unknown): string {\n  return `data: ${JSON.stringify(payload)}\\n\\n`;\n}\n\n/** 请求体读不出来的具体成因：供端点在失败文案里说清是哪一种。 */\nexport type JsonBodyInvalidReason = \"too-large\" | \"unreadable\" | \"malformed\" | \"not-object\";\n\n/** `readJsonBodyOutcome` 的成因可辨结果：缺席（可选 body 未给）/ 合法对象 / 非法（带具体成因）。 */\nexport type JsonBodyOutcome =\n  | { kind: \"absent\" }\n  | { kind: \"json\"; value: object }\n  | { kind: \"invalid\"; reason: JsonBodyInvalidReason };\n\n/**\n * 读请求 body（JSON）并**保留失败成因**。\n *\n * 为什么需要它：`readJsonBody` 把「没给 body」「JSON 畸形」「超出上限」「JSON 合法但不是对象」\n * 收敛成同一个 undefined，调用方想区分「可选 body 缺席」与「给了但读不出来」只能靠猜。对**有副作用**\n * 的端点，这个歧义是有代价的：畸形请求会走到「按缺省处理」那条路，等于拿垃圾输入触发真实动作。\n * 需要 fail-closed 的端点用本函数；宽松端点继续用 `readJsonBody`（它是本函数的薄包装）。\n * @param req - Node http 请求对象（或 async-iterator 桩）。\n * @param limit - 字节上限（默认 2MB）。\n * @returns 成因可辨的结果。\n */\nexport async function readJsonBodyOutcome(\n  req: IncomingMessage,\n  limit = 2 * 1024 * 1024,\n): Promise<JsonBodyOutcome> {\n  const chunks: Buffer[] = [];\n  let size = 0;\n  try {\n    for await (const chunk of req) {\n      size += chunk.length;\n      if (size > limit) return { kind: \"invalid\", reason: \"too-large\" };\n      chunks.push(chunk);\n    }\n  } catch {\n    return { kind: \"invalid\", reason: \"unreadable\" };\n  }\n  let text: string;\n  try {\n    text = Buffer.concat(chunks).toString(\"utf8\");\n  } catch {\n    // 块不是 Buffer（流被 setEncoding 成字符串之类）：与「读不出来」同义。这里必须在 try 内——\n    // 本函数对外的承诺是**不抛错**（宽版面 `readJsonBody` 是它的薄包装），抛出去会打到调用方。\n    return { kind: \"invalid\", reason: \"unreadable\" };\n  }\n  // 空 body（含纯空白）与「没写 body」是同一件事：可选参数缺席，不是错误。\n  if (text.trim() === \"\") return { kind: \"absent\" };\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(text);\n  } catch {\n    return { kind: \"invalid\", reason: \"malformed\" };\n  }\n  if (typeof parsed !== \"object\" || parsed === null)\n    return { kind: \"invalid\", reason: \"not-object\" };\n  return { kind: \"json\", value: parsed };\n}\n\n/**\n * 宽松读请求 body（JSON）：解析失败或超限返回 undefined（不抛错），由调用方决定响应。\n * 成因不可辨——要区分「缺席」与「非法」用 `readJsonBodyOutcome`。与 readBody 共用限长语义。\n * @param req - Node http 请求对象（或 async-iterator 桩）。\n * @param limit - 字节上限（默认 2MB）。\n * @returns 解析后的 JSON 对象；空/非法/超限返回 undefined。\n */\nexport async function readJsonBody(\n  req: IncomingMessage,\n  limit = 2 * 1024 * 1024,\n): Promise<object | undefined> {\n  const outcome = await readJsonBodyOutcome(req, limit);\n  return outcome.kind === \"json\" ? outcome.value : undefined;\n}\n\n/**\n * 把任意抛出的值转成可读错误消息。\n * @param error - 任意抛出的值。\n * @returns 可读错误消息。\n */\nexport function errorMessage(error: unknown): string {\n  try {\n    if (error instanceof Error) return error.message;\n    return String(error);\n  } catch {\n    return \"[unrenderable thrown value]\";\n  }\n}\n\n/**\n * 读请求 body（JSON，限长防滥用）。\n * 兼容两种请求形态：Node 事件流（data/end）与 async-iterator 桩（测试用）。\n * @param req - Node http 请求对象（或 async-iterator 桩）。\n * @param limit - 字节上限（显式传入，默认 256KB）。\n * @returns 解析后的 JSON 对象（空 body 返回 {}）。\n */\nexport function readBody(req: IncomingMessage, limit = 256 * 1024): Promise<object> {\n  // async-iterator 形态（部分测试桩）：逐块读取，限长检查。\n  if (typeof req[Symbol.asyncIterator] === \"function\" && typeof req.on !== \"function\") {\n    return (async () => {\n      const chunks: Buffer[] = [];\n      let size = 0;\n      for await (const chunk of req) {\n        size += chunk.length;\n        if (size > limit) throw new Error(\"body too large\");\n        chunks.push(chunk);\n      }\n      return chunks.length === 0 ? {} : JSON.parse(Buffer.concat(chunks).toString(\"utf8\"));\n    })();\n  }\n  // Node 事件流形态。\n  return new Promise((resolvePromise, reject) => {\n    const chunks: Buffer[] = [];\n    let size = 0;\n    req.on(\"data\", (chunk: Buffer) => {\n      size += chunk.length;\n      if (size > limit) {\n        reject(new Error(\"body too large\"));\n        req.destroy();\n        return;\n      }\n      chunks.push(chunk);\n    });\n    req.on(\"end\", () => {\n      try {\n        resolvePromise(\n          chunks.length === 0 ? {} : JSON.parse(Buffer.concat(chunks).toString(\"utf8\")),\n        );\n      } catch (error) {\n        const e = error as Error;\n        reject(new Error(`invalid JSON body: ${e.message}`));\n      }\n    });\n    req.on(\"error\", reject);\n  });\n}\n"
    },
    {
      "path": "packages/dsh-mcp-manager/src/server/connection/orchestrator/manager.ts",
      "content": "/**\n * dsh-mcp-manager — MCP 服务器管理器（单一事实源）。\n *\n * McpManager 持有全局存储 + 当前会话项目的项目级存储、连接池宿主面与状态通知。\n * 全局服务器常连；项目级服务器（<项目根>/.dsh/@wingsky-1/dsh-mcp-manager/mcp.json）只在当前会话 cwd 属于\n * 该项目时连接（跟随会话切换）。\n *\n * **单池（#767 笔 1a）**：连接只有一本账 = 中间层单元表 `middleware.units`\n * （键 = (root, 裸名)）。此前 manager 自持的那条「直连账本」并行路径已整体退役\n * ——池归属判定（旧 `middlewareTakes`）恒真，本类不再持有任何条目表。\n *\n * 类型自各域门面取；manager.ts 不 import apply.ts / index.ts（防循环引用）。\n */\n\nimport { randomBytes } from \"node:crypto\";\nimport { mkdir, rename, rm, writeFile } from \"node:fs/promises\";\nimport { existsSync } from \"node:fs\";\nimport { dirname } from \"node:path\";\nimport type { SseHub } from \"../../../../../../shared/sse-hub.js\";\nimport type { Context, LoggerService } from \"@deepseek-ai/cordis\";\nimport type { ServerConfig } from \"../../config/interface.ts\";\nimport type { ClientUiConfig, ServerState } from \"../../../shared/interface.ts\";\nimport type { ToolDefinition } from \"@deepseek-ai/dsh-tools\";\nimport type {\n  CatalogCache,\n  CatalogServer,\n  CatalogViewResolver,\n  SchemaView,\n} from \"../../catalog/interface.ts\";\nimport type { McpStore } from \"../../store/interface.ts\";\nimport type { McpStatsCollector } from \"../../stats/interface.ts\";\nimport type { McpMiddleware } from \"../runtime/interface.ts\";\nimport type { ConnectionEntry, ProjectUnit } from \"../interface.ts\";\nimport type { DisabledToolsMap } from \"../../store/interface.ts\";\nimport {\n  EMPTY_STATUS_COUNTS,\n  MIDDLEWARE_GLOBAL_ROOT,\n  SCOPE_GLOBAL,\n  SCOPE_PROJECT,\n  SERVER_STATES,\n} from \"../../../shared/interface.ts\";\nimport { orchestratorPorts } from \"./impl/service/index.ts\";\nimport { fileMode, readTextFile, writeFileAtomic } from \"../../shared/interface.ts\";\n\n/** 期望连接集合的条目：(归属 root, 裸名) 键 → 配置 + scope。 */\ntype DesiredServer = { name: string; server: ServerConfig; scope: string };\n/** 期望连接集合（键 = `${root}\\u0000${name}`；见 buildDesiredServers）。 */\ntype DesiredServers = Map<string, DesiredServer>;\n/** 目录数据源条目（裸名 → 配置 + scope；catalogServersFor 的输出面）。 */\ntype CatalogServers = Map<string, { server: ServerConfig; scope: string }>;\ntype HttpConnection = {\n  state: \"connecting\" | \"failed\";\n  error?: string;\n  failedEntry?: ConnectionEntry;\n};\n\n/** 纯对象表判定（env/headers 表；null 与数组都不算表）。类型谓词，收窄后免断言。 */\nexport function isPlainRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === \"object\" && value !== null && !Array.isArray(value);\n}\n\n/** 投影占位符判定（#770-A3）：含 \"[REDACTED]\" 或其 URL 编码形态。 */\nexport function isProjectionPlaceholder(value: unknown): boolean {\n  return (\n    typeof value === \"string\" && (value.includes(\"[REDACTED]\") || value.includes(\"%5BREDACTED%5D\"))\n  );\n}\n\n/**\n * 写路径 guard 的一格：这一（键, 值）是否携带投影占位符。\n * 口径逐字照搬历史三段判定：args 只看数组元素、env/headers 只看一层值、\n * 其余键只看字符串值本身——不递归（更深的嵌套历史不判，回写形状不变）。\n */\nexport function carriesProjectionPlaceholder(key: string, value: unknown): boolean {\n  if (key === \"args\" && Array.isArray(value)) return value.some(isProjectionPlaceholder);\n  if ((key === \"env\" || key === \"headers\") && isPlainRecord(value))\n    return Object.values(value).some(isProjectionPlaceholder);\n  return isProjectionPlaceholder(value);\n}\n\n/** add 的回写 guard：首个携带投影占位符的键名；无则 undefined（键序即判定序）。 */\nexport function findProjectionPlaceholderKey(server: Record<string, unknown>): string | undefined {\n  for (const [key, value] of Object.entries(server)) {\n    if (carriesProjectionPlaceholder(key, value)) return key;\n  }\n  return undefined;\n}\n\n/**\n * 计算期望连接集合：回答「池里该有哪些 (root, 裸名)？」——全局 store + 项目级 store\n * （同名跨 root 各成一条）+ runtime 注入（同名优先）；释放与触达的执行在\n * reconcileServers 内（不同问题）。\n *\n * 模块函数而非私有方法：类成员会进入 .d.ts 声明块（导出面快照按块比对），\n * 纯内部分拆放模块级才能让导出面零 diff。 */\nfunction buildDesiredServers(\n  store: McpStore,\n  projectStore: McpStore | undefined,\n  runtimeRegistry: Map<string, ServerConfig>,\n  poolRootFor: (scope: string) => string,\n): DesiredServers {\n  const desired: DesiredServers = new Map();\n  const keyFor = (scope: string, name: string): string => `${poolRootFor(scope)}\\u0000${name}`;\n  for (const server of store.data.servers) {\n    desired.set(keyFor(SCOPE_GLOBAL, server.name), {\n      name: server.name,\n      server,\n      scope: SCOPE_GLOBAL,\n    });\n  }\n  if (projectStore !== undefined) {\n    for (const server of projectStore.data.servers) {\n      const key = keyFor(SCOPE_PROJECT, server.name);\n      // 同名跨 root 各成一条（键含 root）——不再「项目级被全局顶掉」。\n      if (!desired.has(key)) {\n        desired.set(key, { name: server.name, server, scope: SCOPE_PROJECT });\n      }\n    }\n  }\n  // 双轨合并：runtimeRegistry（内存态，运行时注入）并入 desired，同名 runtime 优先。\n  for (const [name, server] of runtimeRegistry) {\n    desired.set(keyFor(SCOPE_GLOBAL, name), { name, server, scope: SCOPE_GLOBAL });\n  }\n  return desired;\n}\n\n/**\n * 目录缓存写盘（H2 等价接入，#767 S2-C）：登记路径（`catalogSummaryFile`）经\n * file-io `writeFileAtomic`（mode 取登记表 + 同路径写串行 + 失败清理临时名）；\n * 未登记路径（单测 tmp 覆盖 `catalogCachePath`）回落既有直写形状——`writeFileAtomic`\n * 对未登记路径抛 I6，直接调等于把回落写盘变成 warn（store.save 的 S2-B 同式）。\n * 序列化形状（`{ version: 1, entries }` + 2 空格）逐字节不变：序列化收敛不是本笔的事。\n *\n * 模块函数而非私有方法：类成员会进入 .d.ts 声明块（导出面快照按块比对），\n * 纯内部分拆放模块级才能让导出面零 diff。 */\nasync function writeCatalogCacheFile(file: string, data: string): Promise<void> {\n  let registered = true;\n  try {\n    fileMode(file);\n  } catch {\n    registered = false;\n  }\n  if (registered) {\n    await writeFileAtomic(file, data);\n    return;\n  }\n  const dir = dirname(file);\n  if (!existsSync(dir)) await mkdir(dir, { recursive: true });\n  // R2 硬化（#767 S2-C 筆3）：回落临时名加随机后缀 + 失败清理（与 file-io `writeOnce` 同式）；\n  // mode 沿既有回落形状（无 mode），只补唯一性与清理，不改写盘语义。\n  const tmp = `${file}.${process.pid}.${Date.now().toString(36)}.${randomBytes(6).toString(\"hex\")}.tmp`;\n  try {\n    await writeFile(tmp, data, \"utf8\");\n    await rename(tmp, file);\n  } catch (cause) {\n    await rm(tmp, { force: true }).catch(() => undefined);\n    throw cause;\n  }\n}\n\n/**\n * #770-A3 只读投影：回答「GET /servers 给 GUI 看什么？」——配置中的凭据永不明文下发。\n *\n * - env/headers：敏感值整体省略（字段缺省，不用 \"[REDACTED]\" 占位符——占位符会被\n *   客户端表单原样读回并 PATCH 落盘，把占位符写成真凭据；省略后缺键在写路径即「沿用既有」）。\n *   GUI 需区分「有秘密（空白即保留）」与「无秘密」时看 hasSecrets 布尔。\n * - url：按 B8 仅脱敏 userinfo/searchParams（username/password/查询值替换为\n *   \"[REDACTED]\"，原串形态替换、host/path/查询键保留可诊断）；非法 URL 原样返回。\n * - toolDefinitions/status 不进投影：前者是运行时内存面（含函数，不可序列化），\n *   后者由 summarize 按读时刷新重算。\n *\n * 写路径永不消费投影值：add/update/normalizeServer 只读客户端表单直送的完整配置，\n * 从不读 summary()/summarize() 的产出；投影中的省略（缺键）与脱敏 URL 若被回写，\n * update 经 stripProjectionPatch 丢弃并沿用既有值（回写链由单测锁定）。\n *\n * 模块函数而非私有方法：类成员会进入 .d.ts 声明块（导出面快照按块比对），\n * 纯内部分拆放模块级才能让导出面零 diff。 */\nfunction hasProjectionSecrets(server: ServerConfig): boolean {\n  if (hasSecretTable(server.env)) return true;\n  if (hasSecretTable(server.headers)) return true;\n  return urlCarriesSecrets(server.url);\n}\n\n/** 非空键值表判定（空表与缺省同义：投影里都算「无秘密」）。 */\nexport function hasSecretTable(table: Record<string, string> | undefined): boolean {\n  return table !== undefined && Object.keys(table).length > 0;\n}\n\n/** URL 形态是否携带秘密（userinfo 非空 / 任一查询值非空；非字符串与非法 URL 判无）。 */\nexport function urlCarriesSecrets(url: unknown): boolean {\n  if (typeof url !== \"string\" || url === \"\") return false;\n  try {\n    const parsed = new URL(url);\n    if (parsed.username !== \"\" || parsed.password !== \"\") return true;\n    for (const value of parsed.searchParams.values()) {\n      if (value !== \"\") return true;\n    }\n  } catch {\n    // 非法 URL 无可判秘密，按无秘密处理（normalizeServer 写时仍会拒绝非法 URL）。\n  }\n  return false;\n}\n\n/**\n * URL 只读投影（B8 口径）：仅 userinfo/searchParams 值替换为 \"[REDACTED]\"，\n * host/path/查询键保留。原串形态替换（decoded + percent-encoded 双形态同 B8\n * addSecretPair），非法 URL 原样返回。\n *\n * 模块函数而非私有方法：理由同上（导出面零 diff）。 */\nfunction redactUrlForSummary(url: unknown): string | undefined {\n  if (typeof url !== \"string\" || url === \"\") return undefined;\n  let parsed: URL;\n  try {\n    parsed = new URL(url);\n  } catch {\n    return url;\n  }\n  const secrets = new Set<string>();\n  const addSecret = (value: string): void => {\n    if (value.length === 0) return;\n    secrets.add(value);\n    try {\n      secrets.add(encodeURIComponent(value));\n    } catch {\n      // 编码失败忽略 raw 形态，decoded 已注册（与 pipeline redact 同式）。\n    }\n  };\n  addSecret(parsed.username);\n  addSecret(parsed.password);\n  for (const value of parsed.searchParams.values()) addSecret(value);\n  if (secrets.size === 0) return url;\n  const ordered = [...secrets].sort((left, right) => right.length - left.length);\n  let out = url;\n  for (const secret of ordered) out = out.split(secret).join(\"[REDACTED]\");\n  return out;\n}\n\n/**\n * 单条服务器配置的只读投影（summarize 两分支共用）：安全字段原样带上，\n * env/headers 值省略、url 按 B8 脱敏、附 hasSecrets 布尔。\n *\n * 模块函数而非私有方法：理由同上（导出面零 diff）。 */\nfunction projectServerForSummary(\n  server: ServerConfig,\n  maskSecretArgsForDisplay: (args: readonly string[]) => string[],\n): Record<string, unknown> {\n  const projected = projectBaseFieldsForSummary(server);\n  const transport =\n    server.transport === \"stdio\"\n      ? projectStdioFieldsForSummary(server, maskSecretArgsForDisplay)\n      : { fields: projectHttpFieldsForSummary(server), argsHadSecret: false };\n  Object.assign(projected, transport.fields);\n  projected.hasSecrets = hasProjectionSecrets(server) || transport.argsHadSecret;\n  return projected;\n}\n\n/** 投影基底：name/transport + 四个可选安全字段（缺省即省略；键序固定，勿调换）。 */\nexport function projectBaseFieldsForSummary(server: ServerConfig): Record<string, unknown> {\n  const projected: Record<string, unknown> = {\n    name: server.name,\n    transport: server.transport,\n  };\n  if (server.enabled !== undefined) projected.enabled = server.enabled;\n  if (server.toolCallTimeoutMs !== undefined)\n    projected.toolCallTimeoutMs = server.toolCallTimeoutMs;\n  if (server.reconnect !== undefined) projected.reconnect = server.reconnect;\n  if (server.description !== undefined) projected.description = server.description;\n  return projected;\n}\n\n/**\n * stdio 分支投影（ServerConfig[`transport`] 的 stdio 一侧）：command/args/cwd。\n * env 整体省略（见本块头注释）；有无秘密只经 hasSecrets 告知 GUI。\n * argsHadSecret：凭据形 flag 的参数值确被掩码过（#925，与 pipeline redact 同口径，\n * 掩码口经参数递入以便直测）；flag 名与非秘密元素保留可诊断，掩码值回写时由\n * stripProjectionPatch 丢弃。\n */\nexport function projectStdioFieldsForSummary(\n  server: ServerConfig,\n  maskSecretArgsForDisplay: (args: readonly string[]) => string[],\n): { fields: Record<string, unknown>; argsHadSecret: boolean } {\n  const fields: Record<string, unknown> = {};\n  if (server.command !== undefined) fields.command = server.command;\n  let argsHadSecret = false;\n  if (server.args !== undefined) {\n    const masked = maskSecretArgsForDisplay(server.args);\n    fields.args = masked;\n    argsHadSecret = masked.some((entry) => entry.includes(\"[REDACTED]\"));\n  }\n  if (server.cwd !== undefined) fields.cwd = server.cwd;\n  return { fields, argsHadSecret };\n}\n\n/** streamable-http 分支投影（ServerConfig[`transport`] 的 http 一侧）：url 按 B8 脱敏。headers 整体省略（同 env）。 */\nexport function projectHttpFieldsForSummary(server: ServerConfig): Record<string, unknown> {\n  const fields: Record<string, unknown> = {};\n  const redactedUrl = redactUrlForSummary(server.url);\n  if (redactedUrl !== undefined) fields.url = redactedUrl;\n  return fields;\n}\n\n/**\n * 写路径回写 guard（update 用）：投影值永不落盘——含 \"[REDACTED]\"（及 URL 序列化后的\n * \"%5BREDACTED%5D\"）的 url 整字段丢弃、env/headers 内含占位符的键丢弃（整表被清空则\n * 整字段丢弃），调用方沿既有值保留。add 无既有值可保，命中占位符即抛错（见 add）。\n *\n * 模块函数而非私有方法：理由同上（导出面零 diff）。 */\nfunction stripProjectionPatch(patch: Record<string, unknown>): Record<string, unknown> {\n  const next: Record<string, unknown> = { ...patch };\n  if (isProjectionPlaceholder(next.url)) delete next.url;\n  if (Array.isArray(next.args) && next.args.some(isProjectionPlaceholder)) delete next.args;\n  for (const key of PROJECTION_SECRET_TABLES) {\n    const table = next[key];\n    if (!isPlainRecord(table)) continue;\n    const kept = Object.entries(table).filter(([, value]) => !isProjectionPlaceholder(value));\n    if (kept.length === 0) delete next[key];\n    else next[key] = Object.fromEntries(kept);\n  }\n  return next;\n}\n\n/** 整表省略的两张凭据表（投影与回写 guard 共用同一组键）。 */\nconst PROJECTION_SECRET_TABLES: readonly (\"env\" | \"headers\")[] = [\"env\", \"headers\"];\n\n/** 空 cwd 判定（类型谓词）：undefined / null / \"\" 三形态都判「无项目」，收窄后无需断言。 */\nexport function isBlankCwd(cwd: string | null | undefined): cwd is null | undefined | \"\" {\n  return cwd === undefined || cwd === null || cwd === \"\";\n}\n\n/**\n * 会话 cwd → 项目根（catalogServersFor 与 setSession 共用的同一口径）。\n * 查表口经参数递入：模块级函数因此不依赖端口装配，可直测。\n */\nexport async function projectRootForCwd(\n  cwd: string | undefined,\n  findProjectRoot: (cwd: string | undefined) => Promise<string>,\n): Promise<string | undefined> {\n  if (isBlankCwd(cwd)) return undefined;\n  return findProjectRoot(cwd);\n}\n\n/** (键, 配置) 对适配：store 侧目录键即 server.name（runtimeRegistry 侧用注册表键，见 collectCatalogServers）。 */\nexport function serverEntry(server: ServerConfig): readonly [string, ServerConfig] {\n  return [server.name, server];\n}\n\n/**\n * enabled 的服务器并进目录数据源（同名后者覆盖前者——调用顺序即优先级：\n * 全局 store → runtimeRegistry → 项目级 store，#770-11 项目优先）。\n * 键取 entry 键而非 server.name：runtimeRegistry 的键是注册名，与条目内的 name 不必然同形。\n */\nexport function collectCatalogServers(\n  into: CatalogServers,\n  entries: Iterable<readonly [string, ServerConfig]>,\n  scope: string,\n): void {\n  for (const [name, server] of entries) {\n    if (server.enabled === false) continue;\n    into.set(name, { server, scope });\n  }\n}\n\n/** 重读配置且失败只 warn 不外抛（读路径不该被配置损坏打断）；返回是否变化。 */\nexport async function reloadStoreQuietly(\n  store: McpStore,\n  onFail: (error: unknown) => void,\n): Promise<boolean> {\n  try {\n    return await store.reloadIfChanged();\n  } catch (error) {\n    onFail(error);\n    return false;\n  }\n}\n\n/**\n * 触达单元（fire-and-forget，setSession 永不挂起）：成功即淘汰失效单元。\n * 必须带拒绝处理（#903 M4），否则 projectUnitFor 翻错即 unhandled rejection。\n */\nexport function touchUnitInBackground(\n  middleware: McpMiddleware,\n  target: string,\n  onFail: (error: unknown) => void,\n): void {\n  void middleware.projectUnitFor(target).then(\n    (unit) => {\n      if (unit !== undefined) middleware.evictIfNeeded();\n    },\n    (error: unknown) => onFail(error),\n  );\n}\n\n/** 池内不再需要的连接（配置里已无 / 已禁用）释放；返回是否释放过。 */\nexport function releaseUndesiredConnections(\n  middleware: McpMiddleware | undefined,\n  desired: DesiredServers,\n): boolean {\n  if (middleware === undefined) return false;\n  let released = false;\n  // 单池后「拆」只有这一个落点——旧直连账本的 stop 随账本一并退役。\n  for (const unit of [...middleware.units.values()]) {\n    for (const serverName of [...unit.connections.keys()]) {\n      const want = desired.get(`${unit.root}\\u0000${serverName}`);\n      if (want !== undefined && want.server.enabled !== false) continue;\n      if (middleware.releaseConnection(unit.root, serverName)) released = true;\n    }\n  }\n  return released;\n}\n\n/**\n * 该 (root, 裸名) 是否还不在池里（= 连接集合变化）。中间层缺失时**不算**变化：\n * 实例缺失时什么都触达不了，记变化只会让状态广播空转。\n */\nexport function absentFromPool(\n  middleware: McpMiddleware | undefined,\n  root: string,\n  name: string,\n): boolean {\n  if (middleware === undefined) return false;\n  return !(middleware.units.get(root)?.connections.has(name) ?? false);\n}\n\n/** 触达落点：项目级取当前项目 root（无活动项目即无处触达），全局级落 @global。 */\nexport function touchRootFor(scope: string, projectRoot: string | undefined): string | undefined {\n  return scope === SCOPE_PROJECT ? projectRoot : MIDDLEWARE_GLOBAL_ROOT;\n}\n\n/**\n * 池同步本体（reconcileServers 的执行面，两个变化原因各自成步）：\n * ① 释放池内不再需要的连接；② 触达配置里应有而池内尚缺的条目。返回集合是否变化。\n */\nexport function syncPool(\n  middleware: McpMiddleware | undefined,\n  desired: DesiredServers,\n  projectRoot: string | undefined,\n  start: (name: string, scope: string) => void,\n): boolean {\n  let changed = releaseUndesiredConnections(middleware, desired);\n  for (const want of desired.values()) {\n    if (want.server.enabled === false) continue;\n    const root = touchRootFor(want.scope, projectRoot);\n    if (root === undefined) continue;\n    if (absentFromPool(middleware, root, want.name)) changed = true;\n    // 全部服务器一律经中间层单元触达（单池）：项目级幂等触达当前项目单元，\n    // 全局级触达 @global 单元；两侧都由 start 内部下沉。\n    start(want.name, want.scope);\n  }\n  return changed;\n}\n\n/**\n * connect 的配置来源定位：store 优先；global scope 未命中时回退 runtimeRegistry\n * （F2 #382——runtime 注入条目不落 store）。回退即 warn（口径与旧实现同文案）。\n */\nexport function resolveConnectableServer(\n  store: McpStore,\n  runtimeRegistry: ReadonlyMap<string, ServerConfig>,\n  name: string,\n  scope: string,\n  warn: (message: string) => void,\n): ServerConfig | undefined {\n  const stored = store.find(name);\n  if (stored !== undefined) return stored;\n  if (scope !== SCOPE_GLOBAL) return undefined;\n  const runtime = runtimeRegistry.get(name);\n  if (runtime === undefined) return undefined;\n  warn(`dsh-mcp-manager: server \"${name}\" not in store; using runtime registry entry`);\n  return runtime;\n}\n\n/** 池内已连接条目的 summary 视图输入（由 manager 装配，投影函数不反查池）。 */\ninterface PooledSummaryView {\n  /** 目录可用时的工具名（目录缺失 / 发现失败即空表）。 */\n  tools: readonly string[];\n  /** 本单元的工具禁用集与 @global 继承集（各自可缺省）。 */\n  disabled: ReadonlySet<string> | undefined;\n  inheritedDisabled: ReadonlySet<string> | undefined;\n  /** 读时刷新的六态投影（裁定 U；单元/条目缺失时为 undefined）。 */\n  status: ServerState | undefined;\n  /** 已脱敏的错误文案（连接错误优先、目录发现失败次之）。 */\n  error: string | undefined;\n}\n\n/** 目录可用时的工具名表（目录缺失或发现失败一律空表——解释「connected 却 0 工具」靠 error 而非此处）。 */\nexport function catalogToolNames(catalog: CatalogServer | undefined): string[] {\n  if (catalog === undefined || catalog.unavailable !== undefined) return [];\n  return [...catalog.tools.keys()];\n}\n\n/** 池内条目的错误文案来源：entry.error 优先、目录发现失败次之（脱敏在显示侧做，见 redact 参数）。 */\nexport function pooledErrorText(\n  entry: ConnectionEntry,\n  catalog: CatalogServer | undefined,\n  redact: (error: unknown) => string,\n): string | undefined {\n  const raw = entry.error !== undefined ? entry.error : catalog?.unavailable;\n  return raw === undefined ? undefined : redact(raw);\n}\n\n/** 工具禁用判定：本单元禁用集 ∪ @global 继承集（两者各自可缺省）。 */\nexport function isToolDisabledIn(\n  tool: string,\n  disabled: ReadonlySet<string> | undefined,\n  inheritedDisabled: ReadonlySet<string> | undefined,\n): boolean {\n  return (disabled?.has(tool) ?? false) || (inheritedDisabled?.has(tool) ?? false);\n}\n\n/** 池内条目的 summary 投影（#770-A3 只读基底 + 池面：状态/工具/禁用/错因）。 */\nexport function summarizePooled(\n  base: Record<string, unknown>,\n  scope: string,\n  view: PooledSummaryView,\n): Record<string, unknown> {\n  const disabledList = view.tools.filter((tool) =>\n    isToolDisabledIn(tool, view.disabled, view.inheritedDisabled),\n  );\n  return {\n    ...base,\n    scope,\n    status: view.status,\n    // 目录发现失败（unavailable）时透出原因：解释 connected 却 0 工具。\n    error: view.error,\n    tools: [...view.tools],\n    disabledTools: disabledList.length > 0 ? disabledList : undefined,\n  };\n}\n\n/** 未在池里的条目投影：禁用 → disabled，其余 → stopped，工具面为空（与旧直连账本兜底同口径）。 */\nexport function summarizeAbsent(\n  base: Record<string, unknown>,\n  scope: string,\n  server: ServerConfig,\n): Record<string, unknown> {\n  return {\n    ...base,\n    scope,\n    status: server.enabled === false ? SERVER_STATES.disabled : SERVER_STATES.stopped,\n    error: undefined,\n    tools: [],\n    disabledTools: undefined,\n  };\n}\n\n/**\n * 管理器：持有全局存储 + 当前会话项目的项目级存储、连接池宿主面与状态通知。\n * 全局服务器常连；项目级服务器（<项目根>/.dsh/@wingsky-1/dsh-mcp-manager/mcp.json）只在当前会话 cwd 属于\n * 该项目时连接（跟随会话切换）。\n */\nexport class McpManager {\n  private httpConnections = new Map<string, HttpConnection>();\n  private httpEpochs = new Map<string, number>();\n  private httpSequence = 0;\n  private userStateQueue: Promise<void> = Promise.resolve();\n\n  private connectionKey(root: string, scope: string, name: string): string {\n    return JSON.stringify([root, scope, name]);\n  }\n\n  private invalidateHttpConnection(root: string, scope: string, name: string): void {\n    const key = this.connectionKey(root, scope, name);\n    this.httpEpochs.set(key, ++this.httpSequence);\n    this.httpConnections.delete(key);\n  }\n\n  private markDisabled(mw: McpMiddleware, root: string, name: string): Set<string> {\n    const disabled = mw.disabledByRoot.get(root) ?? new Set<string>();\n    disabled.add(name);\n    mw.disabledByRoot.set(root, disabled);\n    return disabled;\n  }\n\n  async rootForRequest(scope: string, cwd?: string): Promise<string> {\n    if (scope !== SCOPE_PROJECT) return MIDDLEWARE_GLOBAL_ROOT;\n    const captured = this.projectRoot;\n    const root =\n      cwd !== undefined\n        ? await projectRootForCwd(cwd, orchestratorPorts.get().workspace.findProjectRoot)\n        : captured;\n    if (root === undefined)\n      throw new Error(\"no active project session (call session with a cwd first)\");\n    return root;\n  }\n\n  /** HTTP 受理入口；宿主 connect 仍等待完整连接。 */\n  async acceptConnection(name: string, scope: string, cwd?: string): Promise<string> {\n    const started = this.httpSequence;\n    const root = await this.rootForRequest(scope, cwd);\n    const key = this.connectionKey(root, scope, name);\n    const epoch = this.httpEpochs.get(key) ?? 0;\n    if (epoch > started) throw new Error(\"connection request cancelled\");\n    await this.validateHttpTarget(root, scope, name);\n    if ((this.httpEpochs.get(key) ?? 0) !== epoch) throw new Error(\"connection request cancelled\");\n    const mw = this.middleware;\n    if (mw === undefined) throw new Error(\"middleware is not initialized (apply first)\");\n    if (this.httpConnections.get(key)?.state === \"connecting\") return root;\n    const job: HttpConnection = { state: \"connecting\" };\n    this.httpConnections.set(key, job);\n    this.emitStatus();\n    void this.runHttpConnection(mw, root, name, key, job);\n    return root;\n  }\n\n  private async validateHttpTarget(root: string, scope: string, name: string): Promise<void> {\n    const store = scope === SCOPE_PROJECT ? await this.projectStoreFor(root) : this.store;\n    if (store === undefined) throw new Error(`workspace ${root} has no project MCP config`);\n    const server = resolveConnectableServer(store, this.runtimeRegistry, name, scope, (message) =>\n      this.logger.warn(message),\n    );\n    if (server === undefined) throw new Error(`server \"${name}\" not found in ${scope} scope`);\n    if (server.enabled === false) throw new Error(`server \"${name}\" is disabled`);\n  }\n\n  private async runHttpConnection(\n    mw: McpMiddleware,\n    root: string,\n    name: string,\n    key: string,\n    job: HttpConnection,\n  ): Promise<void> {\n    const current = () => this.httpConnections.get(key) === job;\n    try {\n      const unit = await mw.projectUnitFor(root);\n      if (!current()) return;\n      if (unit === undefined) throw new Error(`workspace ${root} has no project MCP config`);\n      unit.userDisabled.delete(name);\n      mw.disabledByRoot.get(root)?.delete(name);\n      await this.saveUserState(mw.units);\n      if (!current()) return;\n      await mw.ensureConnected(root, name, { force: true });\n      if (!current()) return;\n      if (!unit.connections.has(name)) throw new Error(`server \"${name}\" did not start`);\n      this.httpConnections.delete(key);\n    } catch (error) {\n      if (!current()) return;\n      job.state = \"failed\";\n      job.failedEntry = this.entryForRoot(root, name);\n      try {\n        job.error = this.redactError(error);\n      } catch {\n        job.error = \"connection failed\";\n      }\n    }\n    this.emitStatus();\n  }\n\n  private entryForRoot(root: string, name: string): ConnectionEntry | undefined {\n    return this.middleware?.units.get(root)?.connections.get(name);\n  }\n\n  async disconnectForRequest(name: string, scope: string, cwd?: string): Promise<string> {\n    const root = await this.rootForRequest(scope, cwd);\n    const mw = this.middleware;\n    this.invalidateHttpConnection(root, scope, name);\n    if (mw === undefined) return root;\n    const disabled = this.markDisabled(mw, root, name);\n    const unit = mw.units.get(root);\n    if (unit !== undefined) {\n      unit.userDisabled.add(name);\n      mw.releaseConnection(root, name);\n      unit.inFlight.delete(name);\n    }\n    this.emitStatus();\n    const units = new Map(mw.units);\n    if (unit === undefined)\n      units.set(root, {\n        root,\n        connections: new Map(),\n        inFlight: new Map(),\n        userDisabled: disabled,\n        lastTouchedAt: Date.now(),\n      });\n    await this.saveUserState(units);\n    return root;\n  }\n  ctx: Context;\n  store: McpStore;\n  listeners: Set<() => void>;\n  logger: LoggerService;\n  projectRoot: string | undefined;\n  projectStore: McpStore | undefined;\n  reconcileBusy: boolean;\n  projectStores: Map<string, McpStore>;\n  catalogCache: CatalogCache;\n  catalogCachePath: string;\n  uiConfigSource: () => unknown;\n  /** 设置命名空间写入 sink（apply 时经 ctx.inject([\"settings\"]) 注入；注入不到则写不可用）。 */\n  uiUpdate?: (patch: Record<string, unknown>) => Promise<unknown>;\n  /**\n   * SSE 连接枢纽（共享 shared/sse-hub，#515）：makeEventsRoute 惰性创建；\n   * 广播/卸载 disposer 收口到 hub（连接表 + 心跳 + stalled/maxAge 主动回收）。\n   * 取代旧 sseConnections Set + per-connection 心跳（#268）。\n   */\n  sseHub?: SseHub;\n  /** 中间层实例（连接池 + 目录 + 路由；惰性创建）。 */\n  middleware: McpMiddleware | undefined;\n  /** userDisabled 持久化路径。 */\n  userStatePath: string;\n  /** MCP 调用统计收集器（可用于 debug 模式量化调用指标与渐进式披露漏斗）。 */\n  stats: McpStatsCollector;\n  /** 运行时注册表（内存态，不落盘）：供其他插件经 ctx.mcpManager 注入服务器。\n   * 双轨 reconcile：store.data.servers（持久化）+ runtimeRegistry（运行时）。\n   * 同名冲突策略：runtime 优先（运行时注入是「当前会话」语义）。 */\n  runtimeRegistry: Map<string, ServerConfig>;\n  /** registerServer 串行队列（防 reconcileBusy 吞注册；多插件并发注册排队）。 */\n  private registerQueue: Promise<void>;\n  /** 注入端目录缓存视图解析器（catalog/impl/cache-view/index.ts 工厂闭包；含 mtime 缓存）。 */\n  private catalogViewResolver: CatalogViewResolver;\n\n  constructor(ctx: Context, store: McpStore) {\n    const { catalog, configStore, stats } = orchestratorPorts.get();\n    this.ctx = ctx;\n    this.store = store;\n    this.listeners = new Set();\n    this.logger = ctx.logger;\n    this.projectRoot = undefined;\n    this.projectStore = undefined;\n    // 配置重读 → 连接同步的防重入标志（读取路径可并发调用）。\n    this.reconcileBusy = false;\n    // 项目级 store 缓存（root → McpStore）：按工作区缓存配置，切换会话不销毁，\n    // 目录数据源（agent/pre-step）按会话 cwd 从缓存读取，与实时连接状态解耦。\n    this.projectStores = new Map();\n    // 目录缓存：serverName → { summary }（磁盘持久化，digest 的稳定数据源）。\n    this.catalogCache = new Map();\n    this.catalogCachePath = catalog.catalogCacheFile();\n    // 目录视图解析器：host 面用读取器（middleware/模式热切换后取最新引用）。\n    this.catalogViewResolver = catalog.makeCatalogViewFor({\n      getCatalogCache: () => this.catalogCache,\n      getMiddleware: () => this.middleware,\n      catalogCachePathFor: (root) => this.catalogCachePathFor(root),\n    });\n    this.uiConfigSource = () => ({ position: \"top-right\", offsetX: 8, offsetY: 8, blankY: 40 });\n    this.middleware = undefined;\n    this.userStatePath = configStore.userStateFile();\n    this.stats = new stats.McpStatsCollector({ logger: ctx.logger });\n    this.runtimeRegistry = new Map();\n    this.registerQueue = Promise.resolve();\n  }\n\n  /** 读取 settings 命名空间中的 MCP UI 配置（供 /api/dsh-mcp/config 返回）。 */\n  uiConfig(): ClientUiConfig {\n    return orchestratorPorts.get().configModel.normalizeUiConfig(this.uiConfigSource());\n  }\n\n  /**\n   * 写入浮窗 UI 配置（/api/dsh-mcp/config POST）。\n   * 把客户端扁平形态归一化为 `Config.ui` 嵌套补丁，经设置命名空间持久化\n   * （settings.update 落盘 → scope.watch → onChange → SSE 广播一帧），随后返回\n   * 归一化后的最新配置。settings 服务不可用时抛错（写不可用）。\n   */\n  async updateUiConfig(raw: unknown): Promise<ClientUiConfig> {\n    if (typeof this.uiUpdate !== \"function\") {\n      throw new Error(\"ui config is not writable: settings service unavailable\");\n    }\n    await this.uiUpdate({ ui: orchestratorPorts.get().configModel.buildConfigUiPatch(raw) });\n    return this.uiConfig();\n  }\n\n  /** 从磁盘加载目录缓存（损坏/缺失 → 空缓存，不崩溃）。 */\n  async loadCatalogCache(): Promise<void> {\n    try {\n      const raw = await readTextFile(this.catalogCachePath);\n      if (raw === null) return;\n      const parsed = JSON.parse(raw) as { entries?: Record<string, unknown> } | null;\n      if (\n        parsed &&\n        typeof parsed === \"object\" &&\n        typeof parsed.entries === \"object\" &&\n        parsed.entries !== null\n      ) {\n        for (const [name, entry] of Object.entries(parsed.entries)) {\n          if (typeof (entry as { summary?: unknown } | undefined)?.summary === \"string\") {\n            this.catalogCache.set(name, { summary: (entry as { summary: string }).summary });\n          }\n        }\n      }\n    } catch {\n      // 损坏缓存忽略（保持空，下次连接重建）\n    }\n  }\n\n  /**\n   * 连接成功后记录工具描述摘要到目录缓存（**只在摘要实质变化时落盘**——\n   * 保证重连拿到相同描述不触发 digest 变化、不重复注入）。\n   * 缓存是持久数据（磁盘），与实时连接状态解耦：断开/重连不清空 → 目录稳定。\n   */\n  async recordCatalogTools(\n    serverName: string,\n    toolMeta: Map<string, { description?: unknown }>,\n  ): Promise<void> {\n    const summary = orchestratorPorts.get().catalog.summarizeToolDescriptions(toolMeta);\n    const current = this.catalogCache.get(serverName)?.summary;\n    if (summary === undefined || summary === current) return;\n    this.catalogCache.set(serverName, { summary });\n    try {\n      const payload = { version: 1, entries: Object.fromEntries(this.catalogCache) };\n      await writeCatalogCacheFile(this.catalogCachePath, JSON.stringify(payload, null, 2));\n    } catch (error) {\n      this.logger.warn(`dsh-mcp-manager: catalog cache write failed: ${this.redactError(error)}`);\n    }\n  }\n\n  // ------------------------------------------------------------ 直连账本（裁定 AF 形态 B）\n\n  /**\n   * 注册面读口：取不到 / 非数组一律当空——六态投影与工具面投影都不许因为读不到注册表而阻塞\n   * （与 McpMiddleware.registeredSchemas 同口径）。\n   */\n  private registeredSchemas(): SchemaView {\n    const tools = this.ctx?.tools;\n    if (tools === undefined || typeof tools.schemas !== \"function\") return [];\n    try {\n      const schemas = tools.schemas();\n      return Array.isArray(schemas) ? schemas : [];\n    } catch {\n      return [];\n    }\n  }\n\n  /** 单元的 root：项目级取当前项目根，其余取全局虚拟 root（与中间层单元同口径）。 */\n  private poolRootFor(scope: string): string {\n    return scope === SCOPE_PROJECT\n      ? (this.projectRoot ?? MIDDLEWARE_GLOBAL_ROOT)\n      : MIDDLEWARE_GLOBAL_ROOT;\n  }\n\n  /**\n   * 注册名中段 → (root, 裸名) 反查（id 化的 mcp__ 注册名还原成禁用表键）。\n   *\n   * 为什么由 manager 提供：id 是装载期由官方实例的 serverName 定下的（裁定 AG① 明确 id 不进\n   * 注入面），只有自持账本的一侧知道 (id → root, 裸名)。注入端在装配点把这个能力**按入参**递进\n   * guard（与既有 resolveRoot 同一形态），因此不新增跨域值边、也不动任何端口键。\n   */\n  serverNameForId(id: string): { root: string; server: string } | undefined {\n    for (const unit of this.middleware?.units.values() ?? []) {\n      for (const [name, entry] of unit.connections) {\n        if (entry.id === id) return { root: unit.root, server: name };\n      }\n    }\n    return undefined;\n  }\n\n  /**\n   * 公共查询面 `ctx.mcpManager.getTools` 的数据源（M5 = A，本笔换源）：该服务器在\n   * 连接池里的**注册名**清单（`mcp__<id>__<tool>`，与 `ctx.tools` 注册表一致）。\n   *\n   * 口径不变：返回注册名、不是裸名（裸名是 `summary().tools` / 目录读口的口径）。\n   * 数据源从旧直连账本的 `toolMeta` 换成**单元表**——旧实现只由直连路径填充，被中间层\n   * 接管的服务器恒返回 `[]`（既有缺陷 A13/B6）；单池合并后那条路径已不存在。\n   *\n   * 虚拟连接单元（toolDefinitions，无 id/handle）没有宿主注册名，返回空表。\n   */\n  registeredToolsFor(name: string): Array<{ name: string; description?: string }> {\n    const entry = this.poolEntryFor(name);\n    if (entry?.id === undefined) return [];\n    const prefix = `mcp__${entry.id}__`;\n    const tools: Array<{ name: string; description?: string }> = [];\n    for (const schema of this.registeredSchemas()) {\n      const toolName = schema?.name;\n      if (typeof toolName !== \"string\" || !toolName.startsWith(prefix)) continue;\n      tools.push({\n        name: toolName,\n        description: typeof schema.description === \"string\" ? schema.description : undefined,\n      });\n    }\n    return tools;\n  }\n\n  /** 池内该裸名的连接条目（跨单元查；同名跨 root 各成一条，取先命中者，与旧账本同口径）。 */\n  private poolEntryFor(name: string): ConnectionEntry | undefined {\n    for (const unit of this.middleware?.units.values() ?? []) {\n      const entry = unit.connections.get(name);\n      if (entry !== undefined) return entry;\n    }\n    return undefined;\n  }\n\n  onStatus(handler: () => void): () => void {\n    this.listeners.add(handler);\n    return () => this.listeners.delete(handler);\n  }\n\n  /** 脱敏秘密源的唯一事实源（#770-8）：全局 store + 全部 projectStores 缓存 + runtimeRegistry。\n   *\n   * 为什么是同步快照：middleware 的 redact/callTool 与本类的 redactError 都是同步路径，\n   * 而按 root 取配置的 projectServersFor 是 async（同步内不可 await）；脱敏只读已在内存的\n   * 缓存快照，不触发磁盘读。未进缓存的项目 root 不在此列——要读它必须走 async 链（本相按\n   * 裁决不做，调用链保持同步，见 MiddlewareHost.redactionServers）。\n   *\n   * 为什么含 disabled/unconnected：凭据是否出现在错误文案与服务器当下是否启用/已连接\n   * 无关——未连接与 disabled 条目的 secret 同样须抹掉（双向缺口的反例）。此处不做\n   * enabled 过滤，调用方也不得再过滤。\n   *\n   * 三处同调：本方法 ↔ middleware.redact ↔ dispatch redactMcpError（经 host.redactionServers\n   * 转供的同一快照），底层同 pipeline.createRedactor。\n   *\n   * #770-A1：快照在调用方展开 ${ENV} 模板（经 configModel.expandServerEnv）再交\n   * createRedactor——错误文案里出现的是展开后的凭据明文，不是落盘的模板字面量；\n   * redactor 内禁止读 process.env（保持纯函数），展开是调用方的职责。无模板时\n   * 展开恒等（新对象、值不变）；未设置的变量展开为空串，由 addSecretPair 跳过\n   * （空串不注册，避免把空匹配当秘密）。 */\n  getRedactionServers(): ServerConfig[] {\n    const { configModel } = orchestratorPorts.get();\n    const servers: ServerConfig[] = this.store.data.servers.map((server) =>\n      configModel.expandServerEnv(server),\n    );\n    for (const store of this.projectStores.values()) {\n      for (const server of store.data.servers) servers.push(configModel.expandServerEnv(server));\n    }\n    if (\n      this.projectStore !== undefined &&\n      ![...this.projectStores.values()].includes(this.projectStore)\n    ) {\n      for (const server of this.projectStore.data.servers)\n        servers.push(configModel.expandServerEnv(server));\n    }\n    for (const server of this.runtimeRegistry.values())\n      servers.push(configModel.expandServerEnv(server));\n    return servers;\n  }\n\n  /** B8：错误日志脱敏（经 getRedactionServers 全集 + createRedactor）。\n   * 日志与 HTTP body 同口径（C-ERR 契约），error 可能含凭据明文。\n   * #770-A2：公开给路由错误边界（RoutesManager.redactError）——manager 已是\n   * 路由的结构参数，复用同一秘密源，不为 api 域另开脱敏口（附录 G·G19：api 域\n   * 不直持 manager 实例 beyond 既有结构参数，脱敏能力经此方法面递入）。\n   * 每次现建 redactor（per-request 可接受：错误路径低频，无缓存必要）。 */\n  redactError(error: unknown): string {\n    return orchestratorPorts.get().pipeline.createRedactor(this.getRedactionServers())(error);\n  }\n\n  /** coalesce 定时器（同一 tick 内多次状态变化合并为一次广播）。 */\n  private statusTimer: NodeJS.Timeout | undefined;\n\n  /** 状态变化广播（coalesce：同 tick 多次 emitStatus 只广播一次，防 SSE 风暴）。 */\n  emitStatus(): void {\n    if (this.statusTimer !== undefined) return;\n    this.statusTimer = setTimeout(() => {\n      this.statusTimer = undefined;\n      for (const handler of [...this.listeners]) handler();\n    }, 0);\n    this.statusTimer.unref?.();\n  }\n\n  /** 当前会话的项目级存储（无活动项目时抛错）。 */\n  async projectStoreOrThrow(): Promise<McpStore> {\n    if (this.projectStore === undefined) {\n      throw new Error(\"no active project session (call session with a cwd first)\");\n    }\n    return this.projectStore;\n  }\n\n  /**\n   * 中间层宿主：按 root 读取服务器配置。虚拟 root \"@global\" 返回\n   * 全局配置 **+ runtime 注入条目**（#413：runtime 封装定义服务器由中间层接管，\n   * 数据源必须可见；独立合并，不污染 store.data.servers 持久化数组）。\n   */\n  async projectServersFor(root: string): Promise<ServerConfig[] | undefined> {\n    if (root === MIDDLEWARE_GLOBAL_ROOT) {\n      const servers = [...this.store.data.servers];\n      for (const server of this.runtimeRegistry.values()) servers.push(server);\n      return servers;\n    }\n    const store = await this.projectStoreFor(root);\n    return store?.data.servers;\n  }\n\n  /** 中间层宿主：该 server 是否 runtime 注入（目录不写盘判定；#413）。 */\n  isRuntimeServer(name: string): boolean {\n    return this.runtimeRegistry.has(name);\n  }\n\n  /** 中间层宿主：该 server 是否全局级（双源：store + runtimeRegistry）。\n   * runtime 注册的服务器不落 store，单源会误判「非全局」——P1 修正。 */\n  isGlobalServer(name: string): boolean {\n    return (\n      this.store.data.servers.some((server) => server.name === name) ||\n      this.runtimeRegistry.has(name)\n    );\n  }\n\n  /** 中间层宿主：全局服务器配置（@global 单元装载用）。 */\n  globalServers(): ServerConfig[] {\n    return this.store.data.servers;\n  }\n\n  /** 中间层宿主：持久化 userDisabled。 */\n  async saveUserState(units: Map<string, ProjectUnit>): Promise<void> {\n    const snapshot = new Map(\n      [...units].map(([root, unit]) => [\n        root,\n        { ...unit, userDisabled: new Set(unit.userDisabled) },\n      ]),\n    );\n    const write = this.userStateQueue.then(() =>\n      orchestratorPorts.get().configStore.saveUserState(this.userStatePath, snapshot),\n    );\n    this.userStateQueue = write.catch(() => {});\n    await write;\n  }\n\n  /** 中间层宿主：root 的目录缓存文件路径。 */\n  catalogCachePathFor(root: string): string {\n    return orchestratorPorts.get().configStore.catalogCacheFileFor(root);\n  }\n\n  /**\n   * 初始化中间层（apply 时无条件调用；幂等）。单池合并后连接池是唯一连接路径，\n   * 池归属恒为「全部服务器」——#767 笔 2 删掉 `middlewarePolicy` 后不再接受任何入参。\n   */\n  async initMiddleware(): Promise<McpMiddleware> {\n    const { runtime, configStore, workspace } = orchestratorPorts.get();\n    if (this.middleware !== undefined) return this.middleware;\n    const mw = new runtime.McpMiddleware({\n      ctx: this.ctx,\n      logger: this.logger,\n      projectServersFor: (root) => this.projectServersFor(root),\n      redactionServers: () => this.getRedactionServers(),\n      globalServers: () => this.globalServers(),\n      normalizedProjectRoot: (cwd) => workspace.normalizedProjectRoot(cwd),\n      saveUserState: (units) => this.saveUserState(units),\n      emitStatus: () => this.emitStatus(),\n      catalogCachePath: (root) => this.catalogCachePathFor(root),\n      isGlobalServer: (name) => this.isGlobalServer(name),\n      isRuntimeServer: (name) => this.isRuntimeServer(name),\n      recordCatalogTools: (name, tools) => this.recordCatalogTools(name, tools),\n    });\n    try {\n      // 加载 userDisabled 并注入中间层实例（单元创建时合并；重启不丢）。\n      this.disabledByRoot = await configStore.loadUserState(this.userStatePath);\n      mw.disabledByRoot = this.disabledByRoot;\n      // 加载工具级禁用（三层结构；合并式写盘，绝不整表覆盖）。\n      this.disabledTools = await configStore.loadDisabledTools(this.userStatePath);\n      mw.disabledTools = this.disabledTools;\n    } catch (error) {\n      // #392 遗留⑤：加载失败时清理半初始化状态——this.middleware 保持未赋值，\n      // 不会被后续逻辑当已初始化实例使用。\n      this.disabledByRoot = new Map();\n      this.disabledTools = new Map();\n      throw error;\n    }\n    this.middleware = mw;\n    return mw;\n  }\n\n  /** userDisabled 映射（root → Set<server>），中间层单元创建时合并。 */\n  disabledByRoot: Map<string, Set<string>> = new Map();\n\n  /** 工具级禁用（root → server → Set<tool>）；root=@global 跨工作空间共享。 */\n  disabledTools: DisabledToolsMap = new Map();\n\n  /**\n   * 设置/解除单个工具禁用（宿主 API PATCH /api/dsh-mcp/tool-disable 调用）。\n   * 合并式写盘（先读现有文件再覆盖本 root 段，绝不整表覆盖）——\n   * 防多工作空间互相抹掉禁用记录。\n   * @param root 目标 root（全局服务器用 MIDDLEWARE_GLOBAL_ROOT）。\n   * @param server 服务器裸名。\n   * @param tool 远端工具裸名。\n   * @param disabled true=禁用 / false=解除。\n   * 工具级禁用独立于服务器级 enabled：服务器级复活不清工具级状态。\n   */\n  async setToolDisabled(\n    root: string,\n    server: string,\n    tool: string,\n    disabled: boolean,\n  ): Promise<void> {\n    const { configStore } = orchestratorPorts.get();\n    const tools = this.disabledTools.get(root) ?? new Map<string, Set<string>>();\n    const set = tools.get(server) ?? new Set<string>();\n    if (disabled) set.add(tool);\n    else set.delete(tool);\n    if (set.size > 0) tools.set(server, set);\n    else tools.delete(server);\n    if (tools.size > 0) this.disabledTools.set(root, tools);\n    else this.disabledTools.delete(root);\n    await configStore.saveDisabledTools(this.userStatePath, this.disabledTools);\n    this.emitStatus();\n  }\n\n  /** 读取/复用某项目根的 store（工作区缓存命中直接返回，不重复读盘）。 */\n  async projectStoreFor(root: string | undefined): Promise<McpStore | undefined> {\n    if (typeof root !== \"string\" || root === \"\") return undefined;\n    const { configStore, upgrade } = orchestratorPorts.get();\n    let store = this.projectStores.get(root);\n    if (store === undefined) {\n      // 读前落定包分区新形态（S2-D 反转装饰）：触发时机由 upgrade 包装内卡——先搬后读\n      // `await` 串行；`new` 留本侧经既有 ConfigStorePort（upgrade 域不认业务）。落定失败即抛\n      //（禁回落 undefined），回调不执行、不缓存半成品。\n      store = await upgrade.withSettledProjectConfig(root, this.logger, async (settledPath) => {\n        const fresh = new configStore.McpStore(settledPath);\n        await fresh.load();\n        return fresh;\n      });\n      this.projectStores.set(root, store);\n    } else {\n      // 缓存命中也要检查磁盘：项目 mcp.json 在 git 仓库内，pull/checkout/手动\n      // 编辑后应自动生效，不依赖重启宿主（只重读配置，不启停连接）。\n      // #903 M5-A：命中分支同样先过 settle 包装——旧扁平 legacy 在首次缓存后重现\n      // （切旧分支/降级写）时，否则永不归位；settle 幂等，开销仅几次 existsSync。\n      // const 捕获：else 分支的非空收窄进不了回调闭包，直接用外层 store 会 TS18048。\n      const cached = store;\n      try {\n        await upgrade.withSettledProjectConfig(root, this.logger, async () => {\n          await cached.reloadIfChanged();\n        });\n      } catch (error) {\n        this.logger.warn(\n          `dsh-mcp-manager: reload project config failed: ${this.redactError(error)}`,\n        );\n      }\n    }\n    return store;\n  }\n\n  /**\n   * 会话目录数据源：全局服务器 + 该 cwd 所属项目的项目级服务器（**配置层面**，\n   * 与 host 当前 setSession 状态解耦）。此前直接用 manager.supervisors（实时\n   * 连接状态、跟随\"当前工作区\"）——切换工作区会断开/连接项目级服务器，导致\n   * 别的会话的目录集合抖动、每次抖动注入一条目录更新消息。按 cwd 计算后：\n   * 工作区 MCP 没变化 → digest 不变 → 不重新注入。\n   *\n   * 运行时注入（registerServer 的 runtimeRegistry，内存态）同样并入目录数据源\n   * （#359）：插件经运行时注入注册的服务器，连接成功、工具可用，\n   * 但此前不在目录里——模型看不到能力，只能自己翻 CLI。同名 runtime 优先\n   * （与 reconcile 双轨一致）。\n   *\n   * 同名碰撞取项目条目（#770-11，项目优先）：与 buildDesiredServers/reconcile\n   * 同口径——连接层同名跨 root 各成一条（键含 root，谁也不顶谁），目录按裸名\n   * 只取一条时取会话项目那条（scope=SCOPE_PROJECT）。\n   * - 预期 breaking：同名碰撞进目录的配置翻转，模型可见工具集/描述随之变化。\n   *   digest 只含名集合（见 catalog/impl/digest），名集不变时 digest 不变，\n   *   但条目内容仍经 catalogViewFor/compose 进入注入文本。\n   * - summary() 仍列全局 + 项目两条（GUI 两条 vs 模型取其一）属预期，不在此收敛。\n   */\n  async catalogServersFor(cwd: string | undefined): Promise<CatalogServers> {\n    const servers: CatalogServers = new Map();\n    collectCatalogServers(servers, this.store.data.servers.map(serverEntry), SCOPE_GLOBAL);\n    // 运行时注入（registerServer 内存态）：并入目录数据源，同名 runtime 优先。\n    collectCatalogServers(servers, this.runtimeRegistry, SCOPE_GLOBAL);\n    const { workspace } = orchestratorPorts.get();\n    const root = await projectRootForCwd(cwd, workspace.findProjectRoot);\n    if (root === undefined) return servers;\n    const store = await this.projectStoreFor(root);\n    if (store === undefined) return servers;\n    // 同名项目覆盖全局（#770-11 项目优先）：目录按裸名只取一条，取会话项目那条。\n    collectCatalogServers(servers, store.data.servers.map(serverEntry), SCOPE_PROJECT);\n    return servers;\n  }\n\n  /**\n   * 合成注入端目录缓存视图（#569 修复核心）：实现在 catalog/impl/cache-view/index.ts\n   * （makeCatalogViewFor 工厂闭包，含磁盘 last-good mtime 缓存），本方法为\n   * 薄桥接（C-DIR：catalogViewFor 迁出 catalog 域，宿主最小面）。\n   * @param cwd 会话 cwd（与 catalogServersFor 同源解析项目 root）。\n   * @param servers catalogServersFor 的输出（name → { server, scope }）。\n   * @returns CatalogCache 形态视图（name → { summary }），可直接喂 composeCatalogEntries。\n   */\n  async catalogViewFor(\n    cwd: string | undefined,\n    servers: Map<string, { server: ServerConfig; scope: string }>,\n  ): Promise<CatalogCache> {\n    return this.catalogViewResolver(cwd, servers);\n  }\n\n  /**\n   * 会话切换：只切 currentRoot + fire-and-forget 惰性启动（不 await 任何连接）。\n   * 变更点驱动（#111/#228）：POST /api/dsh-mcp/session 永不挂起——连接/发现\n   * 由中间层惰性驱动（per-root in-flight 去重），此处零连接副作用。\n   * 单池后项目级连接恒由中间层池按 root 常驻，切走不断开。\n   */\n  async setSession(cwd: string | undefined): Promise<void> {\n    const { workspace } = orchestratorPorts.get();\n    const root = await projectRootForCwd(cwd, workspace.findProjectRoot);\n    if (root === this.projectRoot && this.projectStore !== undefined) return;\n    // 本就没有活动项目且新会话同样无项目（空 cwd）：保持幂等，避免反复\n    // emitStatus → SSE → 客户端 refresh 的广播循环。\n    if (root === undefined && this.projectStore === undefined) return;\n    // 只切 currentRoot；项目级连接由中间层单元按 root 常驻，切走不断开（单池语义）。\n    this.projectRoot = root;\n    this.projectStore = undefined;\n    if (root !== undefined) {\n      const store = await this.projectStoreFor(root);\n      if (this.projectRoot !== root) return;\n      this.projectStore = store;\n    }\n    // 全局配置同样重读（外部手动编辑 <DSH_HOME>/@wingsky-1/dsh-mcp-manager/mcp.json）。\n    await reloadStoreQuietly(this.store, (error) => {\n      this.logger.warn(`dsh-mcp-manager: reload global config failed: ${this.redactError(error)}`);\n    });\n    if (this.middleware !== undefined) {\n      // 仅触达单元（fire-and-forget 惰性连接在 projectUnitFor 内）。无项目 cwd 也回落\n      // 全局虚拟 root @global——单池后 @global 恒可达（可达性三件套之二）。\n      const target = root ?? MIDDLEWARE_GLOBAL_ROOT;\n      touchUnitInBackground(this.middleware, target, (error) => {\n        // #903 M4：fire-and-forget 必须带拒绝处理，否则 projectServersFor/\n        // ensureRootLoaded 翻错即 unhandled rejection（setSession 永不挂起，但错不能丢）。\n        this.logger.warn(\n          `dsh-mcp-manager: setSession touch unit(${target}) failed: ${this.redactError(error)}`,\n        );\n      });\n    }\n    this.emitStatus();\n  }\n\n  /**\n   * 切回前台可用性恢复：对本次请求工作空间连接的非强制恢复（对齐 SSE forceReconnect 的\n   * 触发时机，不对称其 force 语义，#1120）。\n   * 复用官方管理机制与现有 middleware.ensureConnected 的状态投影/在途去重：\n   * connected/connecting/reconnecting 走现有短路保留代际与官方退避，不以每次\n   * visibilitychange 为由 dispose/restart；entry 缺失、真正失败经正常路径恢复；\n   * userDisabled 绝不复活；显式用户 reconnect/force 保持现有能力走 connect()。\n   *\n   * 不做自研连接或协议 ping：官方挂载层只提供 ready/disposed/工具注册面，无法实时\n   * 区分“有工具注册的健康连接”与“有工具注册的半开连接”——自动恢复不声称检测真实\n   * 健康；半开仍由用户显式重连恢复（README 已知限制）。\n   *\n   * @param cwd 本次请求的会话 cwd：undefined=旧无 body 请求回落既有绑定\n   *   （this.projectRoot ?? @global）；\"\"=新请求明确无工作区，固定 @global，\n   *   不回落到别人的 projectRoot；非空=本次解析并固定 root，不读并发可变的\n   *   manager.projectRoot 字段。\n   */\n  async resumeReconnect(cwd?: string): Promise<void> {\n    const mw = this.middleware;\n    if (mw === undefined) return;\n    const { workspace } = orchestratorPorts.get();\n    let root: string;\n    if (cwd === undefined) {\n      root = this.projectRoot ?? MIDDLEWARE_GLOBAL_ROOT;\n    } else if (cwd === \"\") {\n      root = MIDDLEWARE_GLOBAL_ROOT;\n    } else {\n      root = (await workspace.normalizedProjectRoot(cwd)) ?? MIDDLEWARE_GLOBAL_ROOT;\n    }\n    // 单元缺失（宿主重启/状态丢失）先创建：projectUnitFor 负责惰性连接兜底。\n    const unit = mw.units.get(root) ?? (await mw.projectUnitFor(root));\n    if (unit === undefined) return;\n    // 目标 = 配置全集（本项目/全局的全部 enabled 服务器），而非仅已有 entry。\n    const servers = await this.projectServersFor(root);\n    const targets = (servers ?? [])\n      .filter(\n        (server: ServerConfig) => server.enabled !== false && !unit.userDisabled.has(server.name),\n      )\n      .map((server: ServerConfig) => server.name);\n    await Promise.all(\n      targets.map((name) =>\n        mw.ensureConnected(root, name).catch((error: unknown) => {\n          // 单台恢复失败记 warn 不阻断其余：真正失败不得被无条件吞掉。\n          this.logger.warn(\n            `dsh-mcp-manager: resume ${name}@${root} failed: ${this.redactError(error)}`,\n          );\n        }),\n      ),\n    );\n  }\n\n  /**\n   * 重读磁盘配置（全局 + 当前项目）并同步连接集合。\n   * 供「浮窗刷新」等读取路径调用：外部修改 mcp.json 后无需重启宿主。\n   * 仅在配置或连接集合实际变化时广播，避免空转 SSE → 客户端 refresh 循环。\n   * 变更点驱动（#111）：读取路径不再调用本方法（GET /servers 纯读）；本方法\n   * 仅由 fs.watch 变更点与用户操作 API 调用。\n   *\n   * #616 修复：两次 reloadIfChanged 均为 false（配置未变）时直接早退、不再\n   * reconcile——全局 watcher 监听的是整个 `~/.dsh` 目录，插件自身的\n   * user-state 写盘（saveUserState/saveDisabledTools，浮窗连接/断开必写）会\n   * 触发 watcher 事件；此前无配置变化也走 reconcileServers，是「用户操作\n   * 全局服务器 → 项目级单元被误拆」链路的放大器（根因见 start 内注释）。\n   */\n  async refreshFromDisk(): Promise<void> {\n    let configChanged = await reloadStoreQuietly(this.store, (error) => {\n      this.logger.warn(`dsh-mcp-manager: reload global config failed: ${this.redactError(error)}`);\n    });\n    if (this.projectStore !== undefined) {\n      configChanged =\n        (await reloadStoreQuietly(this.projectStore, (error) => {\n          this.logger.warn(\n            `dsh-mcp-manager: reload project config failed: ${this.redactError(error)}`,\n          );\n        })) || configChanged;\n    }\n    if (!configChanged) return;\n    this.reconcileServers();\n    // 配置变了就广播一帧：接收方（浮窗/客户端）据此回拉 GET /servers。连接集合自身的\n    // 异步结算还会各自 emitStatus（start → ensureConnected 结算路径）。\n    this.emitStatus();\n  }\n\n  /**\n   * 按当前配置同步连接池：池内不再需要的（移除 / 禁用 / 归属 root 已变）释放，\n   * 配置里新增或恢复的经中间层单元触达。\n   *\n   * **键是 (归属 root, 裸名)**（单池后与单元表同构）：同名跨 scope（全局 + 项目级）\n   * 各成一条，不再互相顶掉——旧直连账本按裸名键，同名只能活一个，那条限制随账本退役。\n   * runtime 注入条目仍与 store 全局同名时**优先**（双轨合并，与 summary/catalogServersFor 同口径）。\n   *\n   * 同步方法（触达与释放都是同步发起 + 异步结算）；防重入（读取路径可并发）。\n   * @returns {boolean} 连接集合是否变化（释放了在册连接，或触达了尚未在册的服务器）\n   */\n  reconcileServers(): boolean {\n    if (this.reconcileBusy) return false;\n    this.reconcileBusy = true;\n    try {\n      return syncPool(\n        this.middleware,\n        buildDesiredServers(this.store, this.projectStore, this.runtimeRegistry, (scope) =>\n          this.poolRootFor(scope),\n        ),\n        this.projectRoot,\n        (name, scope) => this.start(name, scope),\n      );\n    } finally {\n      this.reconcileBusy = false;\n    }\n  }\n\n  async startAll(): Promise<void> {\n    for (const server of this.store.data.servers) {\n      if (server.enabled !== false) this.start(server.name, SCOPE_GLOBAL);\n    }\n  }\n\n  /**\n   * 启动一个服务器的连接（单池后唯一的连接路径）。\n   *\n   * 全部服务器都归中间层单元持有：项目级幂等触达当前项目单元，全局级触达 @global\n   * 单元。startAll / add / update / reconcile / registerServer 各入口自动收敛，\n   * 无需逐处特判。配置来源一律是宿主面 `projectServersFor(root)`（store + runtime\n   * 注入并集），因此不再需要「config 直传」入参。\n   *\n   * #616 根因修复保留：项目级分支是幂等触达（projectUnitFor + 单台 ensureConnected），\n   * 不是旧 touchMiddlewareUnit 的整单元拆毁——浮窗连接/断开任意服务器触发的\n   * reconcile 不再把当前项目单元连人带连接整个拆掉。\n   *\n   * 中间层实例缺失（未经 apply 装配）时打 warn 并放弃：不退化成官方直装——那条\n   * 并行路径已退役，硬装会在池不知情的情况下占住官方 serverName 活体预留。\n   */\n  start(name: string, scope: string = SCOPE_GLOBAL): void {\n    if (this.middleware === undefined) {\n      this.logger.warn(\n        `dsh-mcp-manager: 中间层未就绪，服务器 \"${name}\" 的连接未建立（全部服务器只经中间层单元）`,\n      );\n      return;\n    }\n    if (scope === SCOPE_PROJECT) this.ensureMiddlewareServer(name);\n    else this.touchGlobalUnit(name);\n  }\n\n  /**\n   * 触达 @global 单元并确保该全局服务器连接（start 的全局级路径）。\n   * projectUnitFor 首次触达会连带惰性连接全部全局服务器，等价 startAll 语义；\n   * userDisabled 命中不连（与浮窗断开语义一致）。\n   */\n  private touchGlobalUnit(name: string): void {\n    const mw = this.middleware;\n    if (mw === undefined) return;\n    void mw\n      .projectUnitFor(MIDDLEWARE_GLOBAL_ROOT)\n      .then(async (unit) => {\n        if (unit === undefined || unit.userDisabled.has(name)) return;\n        // #903 M4：内层 void 浮空时 ensureConnected 翻错无人接——await 链入外层\n        // .catch（与 ensureMiddlewareServer 同式）。\n        await mw.ensureConnected(MIDDLEWARE_GLOBAL_ROOT, name);\n      })\n      .catch((error: unknown) => {\n        // #392 遗留⑥：不再静默吞错——projectUnitFor 失败时打 warn 日志，\n        // 否则该服务器永不连接且无迹可查（ensureConnected 调用面仍会尝试）。\n        this.logger.warn(\n          `dsh-mcp-manager: touchGlobalUnit(${name}) failed: ${this.redactError(error)}`,\n        );\n      });\n  }\n\n  /**\n   * 幂等触达当前项目单元并确保该服务器连接（#616：start 的中间层项目级接管路径，\n   * 取代旧 touchMiddlewareUnit 的整单元拆毁语义）。\n   * - 单元缺失（宿主重启 / 首次 reconcile）：projectUnitFor 创建 + 惰性连接全部；\n   * - 单元已存在（配置热重载 / 误触发的 reconcile）：保留既有连接，仅对**该**服务器\n   *   ensureConnected（connected/connecting 短路，幂等）；\n   * - entry 已存在但 store 配置已变（手工编辑 mcp.json 热重载）：force 单台重建——\n   *   旧实现的配置生效来自整单元拆毁的副作用，此处改为精确到单台，不殃及同单元\n   *   其他连接。\n   * userDisabled 命中不连（与浮窗断开语义一致）；无活动项目 root 静默返回\n   * （与旧 touchMiddlewareUnit 同口径）。\n   */\n  private ensureMiddlewareServer(name: string, requestedRoot = this.projectRoot): void {\n    const mw = this.middleware;\n    if (mw === undefined || requestedRoot === undefined) return;\n    // 入口捕获 root（评审 P2-3）：.then 回调内不再读 this.projectRoot——\n    // setSession 切换后实例字段已变，沿用调用时快照保证 root 与 unit 配套。\n    const root = requestedRoot;\n    void mw\n      .projectUnitFor(root)\n      .then(async (unit) => {\n        if (unit === undefined || unit.userDisabled.has(name)) return;\n        const current =\n          this.projectStores.get(root)?.find(name) ??\n          (root === this.projectRoot ? this.projectStore?.find(name) : undefined);\n        const entry = unit.connections.get(name);\n        // 配置一致性比对（同源 store 实例）：未重载时 entry.server 与 current\n        // 为同一对象引用恒等；真变更必经 reloadIfChanged → load() 整组换新\n        // 对象（键序由 normalizeServer 固定），内容不同则串必不同——假阴性\n        // 不存在；唯一假阳性是用户手排 mcp.json 键序（值不变）触发一次性\n        // force 重连，重建后自愈、不循环。\n        if (\n          entry !== undefined &&\n          current !== undefined &&\n          JSON.stringify(entry.server) !== JSON.stringify(current)\n        ) {\n          await mw.ensureConnected(root, name, { force: true });\n          return;\n        }\n        await mw.ensureConnected(root, name);\n      })\n      .catch((error: unknown) => {\n        this.logger.warn(\n          `dsh-mcp-manager: ensureMiddlewareServer(${name}) failed: ${this.redactError(error)}`,\n        );\n      });\n  }\n\n  /**\n   * 拆除中间层池中该 server 的连接（update/remove 配置变更后强制重建；\n   * 不写 userDisabled——与 disconnect 的禁用语义区分）。此前 update/remove 仅\n   * 处理项目单元，@global 池连接与目录残留导致「已删服务器仍可调用」。\n   */\n  private dropMiddlewareConnection(name: string, root?: string): void {\n    const mw = this.middleware;\n    if (mw === undefined) return;\n    let dropped = false;\n    for (const unit of mw.units.values()) {\n      if (root !== undefined && unit.root !== root) continue;\n      // 拆除落点统一走账本（裁定 X）：只发起 release、不等结算——拆除路径是同步语义。\n      if (mw.releaseConnection(unit.root, name)) dropped = true;\n      // #392 遗留①：目录条目随连接一并拆除——remove/update 后已删服务器不再以\n      // 幽灵条目出现在 ws_mcp_list / ws_mcp_search（此前只拆连接，目录 TTL 内残留）。\n      // 内存目录先行删除；磁盘 last-good 缓存异步同步（防重启后 loadCatalogCache\n      // 把幽灵条目载回——persistCatalog 空采集不写盘，remove 后目录可能为空，必须\n      // 显式清盘而非依赖全量覆盖写）。\n      const { catalogDirectory } = orchestratorPorts.get().catalog;\n      if (catalogDirectory.entryFor(unit.root, name) !== undefined) {\n        // 内存目录先行删除（原语义：`unit.catalog.delete(name)` 为真才同步清盘）；磁盘\n        // last-good 缓存异步同步，路径由本层算好按入参递入（目录域不推路径）。\n        void catalogDirectory\n          .removeRootEntry(unit.root, name, {\n            cachePath: this.catalogCachePathFor(unit.root),\n            warn: (message) => this.logger.warn(message),\n          })\n          .catch(() => {});\n        catalogDirectory.dropServer(unit.root, name);\n        dropped = true;\n      }\n    }\n    // 拆除即废弃同名在途建连标记：entry 被强拆后旧 attempt 仍可能 pending 至\n    // CONNECT_TIMEOUT_MS，残留去重标记会吞掉 remove/update 后的同名重连（含\n    // 重加配置立即重建）——详见 middleware.abandonInFlight 不变式。\n    if (root === undefined) mw.abandonInFlight(name);\n    else mw.units.get(root)?.inFlight.delete(name);\n    if (dropped) this.emitStatus();\n  }\n\n  /**\n   * 运行时注册服务器（内存态，不落盘）。\n   * 供其他插件经 ctx.mcpManager 注入（官方 storageDomain service 模式）。\n   * - 同名已存在（store 或 runtime）：返回 { name, existing: true }，不抛错；\n   * - 注册即连接（走 start 的 config 直传分支，同名 runtime 优先）；\n   * - 串行队列防 reconcileBusy 吞注册；多插件并发注册排队。\n   * @param options 注册入参；`toolDefinitions` 可选——提供时该服务器工具\n   *   全部用调用方封装定义注册（supervisor 跳过远端 schema 投影，execute\n   *   来自调用方；命名仍按 publicToolName 的 mcp__ 前缀规则）。\n   */\n  async registerServer(\n    options: Record<string, unknown>,\n  ): Promise<{ name: string; existing: boolean }> {\n    const { toolDefinitions, ...rest } = options;\n    const config = orchestratorPorts.get().configModel.normalizeServer(rest);\n    // R4：内存态不走 assertEnvPolicy——不落盘即无 baked 风险，调用方本就持有 process.env。\n    if (Array.isArray(toolDefinitions))\n      config.toolDefinitions = toolDefinitions as ToolDefinition[];\n    const run = this.registerQueue.then(async () => {\n      if (this.runtimeRegistry.has(config.name) || this.store.find(config.name) !== undefined) {\n        return { name: config.name, existing: true };\n      }\n      this.runtimeRegistry.set(config.name, config);\n      // #413 时序显式化：注册即连接走 start。单池后 runtime 条目与 store 全局条目\n      // 同路——@global 单元的配置数据源（projectServersFor）已并入 runtimeRegistry，\n      // 因此不需要 config 直传。中间层未就绪窗口（provide→initMiddleware 之间的\n      // async 空隙）start 会 warn 并不建连接，由 apply 的 reconcileServers\n      // （initMiddleware 后无条件执行）按同一口径补齐。\n      if (config.enabled !== false) this.start(config.name, SCOPE_GLOBAL);\n      return { name: config.name, existing: false };\n    });\n    this.registerQueue = run.then(\n      () => undefined,\n      () => undefined,\n    );\n    return run;\n  }\n\n  /**\n   * 运行时注销（不影响 store 持久化条目；同名 store 条目回落）。\n   * - **先删 runtimeRegistry 再拆中间层连接**（#413 QA P2-1）：drop 时数据源\n   *   （projectServersFor 含 runtime）已不再返回该服务器，任何并发\n   *   ensureConnected/connect 都查不到配置而无法重建虚拟连接——堵死注销后\n   *   瞬时复活窗口，且不写 userDisabled（避免持久化污染导致同名 re-register\n   *   被静默阻止连接，与 disconnect 的「用户主动断开」语义区分）；\n   * - 拆中间层连接与目录条目（#413：runtime 条目在 @global 单元，须显式清理，\n   *   否则 unregister 后 ws_mcp_list/call 残留幽灵）；\n   * - reconcile 回落 store 配置。\n   */\n  async unregisterServer(name: string): Promise<void> {\n    const run = this.registerQueue.then(async () => {\n      if (this.runtimeRegistry.has(name)) {\n        this.runtimeRegistry.delete(name);\n        // 单池后「拆」统一走池账本（旧直连账本的 stop 已随账本退役）。\n        this.dropMiddlewareConnection(name);\n        this.reconcileServers();\n      }\n    });\n    this.registerQueue = run.then(\n      () => undefined,\n      () => undefined,\n    );\n    return run;\n  }\n\n  async add(server: Record<string, unknown>, scope: string = SCOPE_GLOBAL): Promise<ServerConfig> {\n    // #770-A3 回写 guard：新建无既有值可保，投影占位符进写路径即抛错（调用方重填真值）。\n    const placeholderKey = findProjectionPlaceholderKey(server);\n    if (placeholderKey !== undefined) {\n      throw new Error(\n        `server ${JSON.stringify(placeholderKey)} must not contain projection placeholder \"[REDACTED]\" (re-enter the real value)`,\n      );\n    }\n    const config = orchestratorPorts.get().configModel.normalizeServer(server);\n    // #770-2 环境净化：写边界凭据策略门（与 update/import 同门；normalize 保持纯形状校验）。\n    orchestratorPorts\n      .get()\n      .configModel.assertEnvPolicy(config.env, config.headers, undefined, config.url, config.args);\n    const store = scope === SCOPE_PROJECT ? await this.projectStoreOrThrow() : this.store;\n    if (store.find(config.name) !== undefined) {\n      throw new Error(`server \"${config.name}\" already exists in ${scope} scope`);\n    }\n    store.upsert(config);\n    await store.save();\n    // #616：中间层项目级此前在此 touchMiddlewareUnit() 拆毁整个当前单元——\n    // 新服务器经下方 start → ensureMiddlewareServer 幂等补连即可生效，无需\n    // 拆毁单元殃及既有项目级连接。\n    if (config.enabled !== false) this.start(config.name, scope);\n    return config;\n  }\n\n  async update(\n    name: string,\n    patch: Record<string, unknown>,\n    scope: string = SCOPE_GLOBAL,\n    cwd?: string,\n  ): Promise<ServerConfig> {\n    const { configModel } = orchestratorPorts.get();\n    const root = await this.rootForRequest(scope, cwd);\n    const store = await this.storeForRoot(root, scope);\n    const existing = store.find(name);\n    if (existing === undefined) throw new Error(`server \"${name}\" not found in ${scope} scope`);\n    // #770-A3 回写 guard：投影值永不落盘——占位符 URL/键丢弃并沿用既有值（缺键即保留，\n    // 与客户端省略语义同源）；客户端直调投影 payload 亦被此处兜底。\n    const merged = configModel.normalizeServer({\n      ...existing,\n      ...stripProjectionPatch(patch),\n      name,\n    });\n    // #770-2 环境净化：写边界凭据策略门（审合并后落盘形态；与 add/import 同门）。\n    configModel.assertEnvPolicy(merged.env, merged.headers, undefined, merged.url, merged.args);\n    const revision = this.reserveUpdate(root, scope, name);\n    store.upsert(merged);\n    this.cancelDisabledUpdate(root, scope, name, merged);\n    await store.save();\n    if (!this.ownsUpdate(revision)) return merged;\n    // 单池后「拆旧配置连接」只有池账本一个落点（项目/全局单元统一处理；\n    // #382 此前只拆项目单元，全局旧连接残留导致编辑不生效）。\n    this.invalidateHttpConnection(root, scope, name);\n    this.dropMiddlewareConnection(name, root);\n    if (patch.enabled === true)\n      await this.acceptConnection(name, scope, scope === SCOPE_PROJECT ? root : undefined);\n    else this.startUpdatedServer(root, scope, name, merged);\n    return merged;\n  }\n\n  private async storeForRoot(root: string, scope: string): Promise<McpStore> {\n    if (scope !== SCOPE_PROJECT) return this.store;\n    const store =\n      this.projectStores.get(root) ??\n      (this.projectRoot === root ? this.projectStore : undefined) ??\n      (await this.projectStoreFor(root));\n    if (store === undefined) throw new Error(`workspace ${root} has no project MCP config`);\n    return store;\n  }\n\n  private reserveUpdate(\n    root: string | undefined,\n    scope: string,\n    name: string,\n  ): { key: string; epoch: number } | undefined {\n    if (root === undefined) return undefined;\n    const key = this.connectionKey(root, scope, name);\n    const epoch = ++this.httpSequence;\n    this.httpEpochs.set(key, epoch);\n    return { key, epoch };\n  }\n\n  private ownsUpdate(revision: { key: string; epoch: number } | undefined): boolean {\n    return revision === undefined || this.httpEpochs.get(revision.key) === revision.epoch;\n  }\n\n  private cancelDisabledUpdate(\n    root: string | undefined,\n    scope: string,\n    name: string,\n    server: ServerConfig,\n  ): void {\n    if (root === undefined || server.enabled !== false) return;\n    const key = this.connectionKey(root, scope, name);\n    this.httpConnections.delete(key);\n    const unit = this.middleware?.units.get(root);\n    if (unit !== undefined) {\n      this.middleware?.releaseConnection(root, name);\n      unit.inFlight.delete(name);\n    }\n    this.emitStatus();\n  }\n\n  private startUpdatedServer(\n    root: string | undefined,\n    scope: string,\n    name: string,\n    server: ServerConfig,\n  ): void {\n    if (server.enabled === false) return;\n    if (scope === SCOPE_PROJECT) this.ensureMiddlewareServer(name, root);\n    else this.start(name, scope);\n  }\n\n  async remove(name: string, scope: string = SCOPE_GLOBAL, cwd?: string): Promise<void> {\n    const root = await this.rootForRequest(scope, cwd);\n    const store = await this.storeForRoot(root, scope);\n    this.invalidateHttpConnection(root, scope, name);\n    // 单池后「拆」统一走池账本（含目录条目清理，防 remove 后 ws_mcp_call 仍可调用）。\n    this.dropMiddlewareConnection(name, root);\n    store.remove(name);\n    await store.save();\n  }\n\n  /**\n   * 显式连接（浮窗「连接」/ 宿主 API）：解除 userDisabled + force 受控重建。\n   *\n   * 单池后只有一条路径——中间层单元：按 scope 定位 root 单元、清 userDisabled、\n   * force 重建该连接。#412：force 是必需的——entry 可能半开卡在 connected，\n   * ensureConnected 的 connected 短路会让显式「连接」看起来无效。\n   */\n  async connect(name: string, scope: string = SCOPE_GLOBAL): Promise<void> {\n    const store = scope === SCOPE_PROJECT ? await this.projectStoreOrThrow() : this.store;\n    // F2（#382）：runtime 注入条目不落 store，global scope 查不到时回退\n    // runtimeRegistry（与 summary/catalogServersFor 同口径）。\n    const server = resolveConnectableServer(store, this.runtimeRegistry, name, scope, (message) =>\n      this.logger.warn(message),\n    );\n    if (server === undefined) throw new Error(`server \"${name}\" not found in ${scope} scope`);\n    const mw = this.middleware;\n    if (mw === undefined) throw new Error(\"middleware is not initialized (apply first)\");\n    const root = scope === SCOPE_PROJECT ? this.projectRoot : MIDDLEWARE_GLOBAL_ROOT;\n    if (root === undefined)\n      throw new Error(\"no active project session (call session with a cwd first)\");\n    const unit = await mw.projectUnitFor(root);\n    if (unit === undefined) throw new Error(`workspace ${root} has no project MCP config`);\n    unit.userDisabled.delete(name);\n    mw.disabledByRoot.get(root)?.delete(name);\n    await this.saveUserState(mw.units);\n    // force 受控重建（#412）：半开卡在 connected 的连接也强制重建（切回前台/刷新\n    // 都走同一入口）。\n    await mw.ensureConnected(root, name, { force: true });\n  }\n\n  /**\n   * 显式断开（浮窗「断开」/ 宿主 API）：写 userDisabled + 拆池内连接。\n   *\n   * 定位（单池后只剩池这一侧）：\n   * - scope=project → 当前项目 root 单元（#392：避免同名全局服务器把项目级断开错写进 @global）；\n   * - 全局配置（store，非 runtime）→ @global 单元（#382：不按 units 遍历序猜）；\n   * - 其余（runtime 注入等）→ 遍历命中该条目的单元。\n   * 前置约束（#770-11 C/A 相）：无 scope 同名调用仍按上法定 @global，而目录\n   * （catalogServersFor）同名取项目——两者分叉；无 scope 调用方须显式传 scope\n   * （#392 同式），本相不动 API 缺省（路由层缺 scope 即归一化为 global）。\n   * 拆除只发起不等结算（裁定 V）：官方 dispose 会等在途首连，挂死的服务器能把它拖到 SDK 的 60s 超时。\n   */\n  async disconnect(name: string, scope?: string): Promise<void> {\n    const mw = this.middleware;\n    if (mw === undefined) return;\n    let targetUnit: ProjectUnit | undefined;\n    const scoped = orchestratorPorts.get().workspace.normalizeScope(scope ?? \"\");\n    const requestRoot = scoped === SCOPE_PROJECT ? this.projectRoot : MIDDLEWARE_GLOBAL_ROOT;\n    if (requestRoot !== undefined) this.invalidateHttpConnection(requestRoot, scoped, name);\n    if (scoped === SCOPE_PROJECT) {\n      targetUnit = this.projectRoot !== undefined ? mw.units.get(this.projectRoot) : undefined;\n    } else if (scope !== undefined || this.store.find(name) !== undefined) {\n      targetUnit = mw.units.get(MIDDLEWARE_GLOBAL_ROOT);\n    } else {\n      targetUnit = [...mw.units.values()].find(\n        (unit) => unit.connections.has(name) || unit.userDisabled.has(name),\n      );\n    }\n    if (targetUnit === undefined) return;\n    targetUnit.userDisabled.add(name);\n    this.markDisabled(mw, targetUnit.root, name);\n    mw.releaseConnection(targetUnit.root, name);\n    // 断开即废弃同名在途标记：拆除时旧 attempt 仍 pending（挂至超时）会吞掉\n    // 紧随的显式「连接」（connect→ensureConnected 去重短路，force 也不豁免）。\n    targetUnit.in